class FakeMessageBot:
    """Stand-in for telegram.Bot as seen from a message, recording
    deleted messages. Referral notices (16 Nov 2026) also send
    through it: sent records (chat_id, text)."""

    def __init__(self):
        self.deleted = []
        self.sent = []

    async def delete_message(self, chat_id, message_id):
        self.deleted.append((chat_id, message_id))

    async def send_message(self, chat_id, text, reply_markup=None):
        self.sent.append((chat_id, text))


class FakeSentMessage:
    """Stand-in for a sent telegram.Message (only its id matters)."""

    def __init__(self, message_id):
        self.message_id = message_id


class FakeMessage:
    """Stand-in for a telegram.Message, recording what was sent."""

    def __init__(self, text=""):
        self.text = text
        self.text_sent = []
        self.voice_sent = []
        self.photos_sent = []
        self.photo_markups = []
        self.markups = []
        self.chat_id = 1
        self.bot = FakeMessageBot()
        self._next_message_id = 0

    def get_bot(self):
        return self.bot

    async def reply_text(self, text, reply_markup=None):
        self.text_sent.append(text)
        self.markups.append(reply_markup)
        self._next_message_id += 1
        return FakeSentMessage(self._next_message_id)

    async def reply_voice(self, voice):
        self.voice_sent.append(voice)
        self._next_message_id += 1
        return FakeSentMessage(self._next_message_id)

    async def reply_photo(self, photo, caption=None, reply_markup=None):
        self.photos_sent.append((photo, caption))
        self.photo_markups.append(reply_markup)
        self._next_message_id += 1
        return FakeSentMessage(self._next_message_id)


class FakeAnimationFile:
    """Stand-in for a downloaded Telegram file (animation/sticker)."""

    def __init__(self, data=b"fake-media-bytes"):
        self._data = data

    async def download_as_bytearray(self):
        return bytearray(self._data)


class FakeAnimation:
    """Stand-in for a telegram.Animation (a GIF is an MP4)."""

    def __init__(self, data=b"fake-mp4-bytes", file_size=100):
        self._data = data
        self.file_size = file_size

    async def get_file(self):
        return FakeAnimationFile(self._data)


class FakeSticker:
    """Stand-in for a telegram.Sticker: static webp by default,
    video (.webm) when is_video, animated (.tgs) when is_animated."""

    def __init__(self, emoji=None, data=b"fake-webp-bytes",
                 file_size=100, is_video=False, is_animated=False):
        self.emoji = emoji
        self._data = data
        self.file_size = file_size
        self.is_video = is_video
        self.is_animated = is_animated

    async def get_file(self):
        return FakeAnimationFile(self._data)


class TestVoiceStyle(unittest.TestCase):
    def test_voice_prompt_is_williams_complete_prompt(self):
        # The owner's voice prompt, pasted verbatim. If any of these
        # phrases is missing, the prompt was edited down by mistake.
        # (Whitespace is normalised first: the prompt is wrapped across
        # lines in the source, but the words are exactly as pasted.)
        p = " ".join(bot.VOICE_STYLE_PROMPT.split())
        self.assertIn("expert Amharic voice actor", p)
        self.assertIn("short-form sponsor segment", p)
        self.assertIn("calm, confident podcast host", p)
        self.assertIn("not a TV commercial", p)
        self.assertIn("never a direct translation feel from English", p)
        self.assertIn("matured native speaker", p)
        self.assertIn("The voice and the language together", p)

    def test_tts_payload_shape_amharic(self):
        payload = bot.build_tts_payload("ሰላም!", "am")
        self.assertEqual(payload["input"], {"text": "ሰላም!"})
        self.assertEqual(payload["voice"]["languageCode"], "am-ET")
        self.assertEqual(payload["voice"]["name"], "am-ET-Wavenet-A")
        audio = payload["audioConfig"]
        self.assertEqual(audio["audioEncoding"], "OGG_OPUS")
        self.assertEqual(audio["speakingRate"], 1.0)
        self.assertEqual(audio["pitch"], 0)

    def test_tts_payload_shape_english(self):
        payload = bot.build_tts_payload("Hello!", "en")
        self.assertEqual(payload["input"], {"text": "Hello!"})
        self.assertEqual(payload["voice"]["languageCode"], "en-US")
        self.assertEqual(payload["voice"]["name"], "en-US-Wavenet-D")
        self.assertEqual(payload["audioConfig"]["audioEncoding"], "OGG_OPUS")

    def test_tts_payload_unsupported_language_returns_none(self):
        # The bot never guesses a voice for a language it has none for.
        self.assertIsNone(bot.build_tts_payload("Bonjour!", "fr"))
        self.assertIsNone(bot.build_tts_payload("Bonjour!", "xx"))

    def test_tts_voice_env_overrides(self):
        with mock.patch.object(bot, "GOOGLE_CLOUD_TTS_VOICE", "am-ET-Standard-B"), \
             mock.patch.object(bot, "GOOGLE_CLOUD_TTS_VOICE_EN", "en-US-Wavenet-C"):
            self.assertEqual(
                bot.build_tts_payload("ሰላም!", "am")["voice"]["name"],
                "am-ET-Standard-B",
            )
            self.assertEqual(
                bot.build_tts_payload("Hello!", "en")["voice"]["name"],
                "en-US-Wavenet-C",
            )


class TestVoiceReply(unittest.IsolatedAsyncioTestCase):
    async def test_speak_reply_none_when_tts_returns_no_audio(self):
        # This is the no-key / API-failure case: the pipeline returns
        # None and the caller falls back to text.
        with mock.patch("bot.cloud_tts_speak", return_value=None):
            self.assertIsNone(await bot.speak_reply("ሰላም!", "am"))

    async def test_speak_reply_returns_ogg(self):
        # Cloud TTS returns OGG Opus directly — no conversion step.
        with mock.patch("bot.cloud_tts_speak", return_value=b"OggS-fake"):
            self.assertEqual(await bot.speak_reply("Hello!", "en"), b"OggS-fake")

    async def test_speak_reply_skips_long_text(self):
        with mock.patch("bot.cloud_tts_speak") as speak:
            self.assertIsNone(await bot.speak_reply("x" * 5000, "en"))
            speak.assert_not_called()

    async def test_reply_message_voice_success(self):
        msg = FakeMessage()
        with mock.patch("bot.speak_reply", return_value=b"OggS-fake"):
            await bot.reply_message(msg, "Hello!", "en", voice=True)
        self.assertEqual(len(msg.voice_sent), 1)
        self.assertEqual(msg.text_sent, [])

    async def test_reply_message_falls_back_to_text(self):
        msg = FakeMessage()
        with mock.patch("bot.speak_reply", return_value=None):
            await bot.reply_message(msg, "Hello!", "en", voice=True)
        self.assertEqual(msg.text_sent, ["Hello!"])
        self.assertEqual(msg.voice_sent, [])

    async def test_reply_message_markup_forces_text(self):
        # The Confirm card carries buttons, so it is always text even
        # when the user spoke — a voice message cannot carry buttons.
        msg = FakeMessage()
        with mock.patch("bot.speak_reply") as speak:
            await bot.reply_message(
                msg, "Confirm?", "en", voice=True, reply_markup="KB"
            )
        speak.assert_not_called()
        self.assertEqual(msg.text_sent, ["Confirm?"])
        self.assertEqual(msg.voice_sent, [])


class TestStripDashes(unittest.IsolatedAsyncioTestCase):
    """No long dash (em dash) in any bot reply (owner, 17 Nov 2026).

    A spaced dash becomes a comma so words never join together; a
    bare dash becomes a space. Hyphen-minuses and en-dash ranges
    (e.g. "10-20", "22:00–07:00 EAT") are not em dashes and pass
    through untouched."""

    def test_spaced_dash_becomes_comma(self):
        self.assertEqual(
            bot._strip_dashes("I did not understand — please try again."),
            "I did not understand, please try again.",
        )

    def test_bare_dash_becomes_space(self):
        self.assertEqual(
            bot._strip_dashes("Instagram—Followers"),
            "Instagram Followers",
        )

    def test_no_dash_text_unchanged(self):
        self.assertEqual(
            bot._strip_dashes("10-20 followers for 22:00–07:00 EAT"),
            "10-20 followers for 22:00–07:00 EAT",
        )
        self.assertEqual(bot._strip_dashes("plain text"), "plain text")

    def test_t_strips_dash(self):
        text = bot.t("not_understood", "en")
        self.assertNotIn("—", text)
        self.assertEqual(
            text,
            "I did not understand, please try again. For example: "
            "“I want 1000 Instagram followers” with your link.",
        )

    def test_t_strips_dash_in_substituted_value(self):
        text = bot.t(
            "batch_missing", "en",
            understood="Instagram Followers — Fast", missing="link",
        )
        self.assertEqual(
            text, "I understood:\nInstagram Followers, Fast\nMissing:\nlink",
        )

    async def test_reply_message_strips_ai_dash(self):
        msg = FakeMessage()
        await bot.reply_message(
            msg, "Price — 1,260 ETB per 1000, fastest first", "en",
        )
        self.assertEqual(
            msg.text_sent, ["Price, 1,260 ETB per 1000, fastest first"],
        )

    async def test_reply_message_voice_fallback_strips_dash(self):
        msg = FakeMessage()
        with mock.patch("bot.speak_reply", return_value=None):
            await bot.reply_message(
                msg, "Hello — what would you like to order?",
                "en", voice=True,
            )
        self.assertEqual(
            msg.text_sent, ["Hello, what would you like to order?"],
        )
        self.assertEqual(msg.voice_sent, [])

    def test_confirm_card_no_dash_when_no_average_time(self):
        service = {
            "name": "Instagram Followers | Fast", "service": 1001,
            "average_time": None, "rate_etb_per_1000": 42.0,
        }
        card = bot.confirm_card_text(
            "en", service, 1000, 42.0, "https://instagram.com/p/x",
        )
        self.assertNotIn("—", card)
        self.assertIn("n/a", card)

    def test_confirm_card_strips_dash_in_service_name(self):
        service = {
            "name": "Instagram—Followers | Fast", "service": 1001,
            "average_time": "5 minutes", "rate_etb_per_1000": 42.0,
        }
        card = bot.confirm_card_text(
            "en", service, 1000, 42.0, "https://instagram.com/p/x",
            full_name=True,
        )
        self.assertNotIn("—", card)

    def test_confirm_card_hides_service_id_when_none_given(self):
        # Owner rule, 20 Nov 2026: when the user gave no service
        # ID, the Confirm card shows the name only — no service
        # number anywhere on it.
        service = {
            "name": "Instagram Followers | Fast", "service": 1001,
            "average_time": "5 minutes", "rate_etb_per_1000": 42.0,
        }
        card = bot.confirm_card_text(
            "en", service, 1000, 42.0, "https://instagram.com/p/x",
        )
        self.assertIn("Instagram Followers", card)
        self.assertNotIn("(#", card)
        self.assertNotIn("#1001", card)
        self.assertNotIn("1001", card)

    def test_confirm_card_shows_service_id_when_given(self):
        # The same card with an entered ID still shows it.
        service = {
            "name": "Instagram Followers | Fast", "service": 1001,
            "average_time": "5 minutes", "rate_etb_per_1000": 42.0,
        }
        card = bot.confirm_card_text(
            "en", service, 1000, 42.0, "https://instagram.com/p/x",
            full_name=True,
        )
        self.assertIn("Instagram Followers | Fast (#1001)", card)

    async def test_notify_user_strips_dash(self):
        app = FakeApp()
        with mock.patch("bot.in_quiet_hours", return_value=False):
            await bot.notify_user(
                app, 1, "Service paused — 3 provider cancels today.",
            )
        self.assertEqual(
            app.bot.sent, [(1, "Service paused, 3 provider cancels today.")],
        )

    async def test_send_order_result_strips_humor_dash(self):
        # The order-placed confirmation is a direct reply_text, not
        # reply_message — and it appends a humour line ("Order in —
        # nice choice!"). The sent text must still come out clean.
        bot.HUMOR_INDEX.pop(1, None)
        result = {
            "service": "Instagram Followers", "quantity": 1000,
            "link": "https://instagram.com/p/x", "total": 42.0,
            "order_id": "1827", "status": "pending",
        }
        msg = FakeMessage()
        with mock.patch(
            "bot.place_pending_order",
            new=mock.AsyncMock(return_value=(result, None)),
        ), mock.patch(
            "bot._maybe_start_auto_repeat",
            new=mock.AsyncMock(return_value=False),
        ):
            await bot.send_order_result(msg, "en", {}, 1)
        self.assertEqual(len(msg.text_sent), 2)
        self.assertNotIn("—", "".join(msg.text_sent))
        self.assertIn("🎉 Order in, nice choice!", msg.text_sent[0])

    async def test_media_reply_strips_ai_dash(self):
        # A bare-emoji reply is a direct reply_text too, and the
        # text can be raw AI output ("Nice one — love it!").
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.media_ai_reply",
            new=mock.AsyncMock(return_value="Nice one — love it!"),
        ), mock.patch(
            "bot.media_order_context",
            new=mock.AsyncMock(return_value={}),
        ):
            await bot.media_reply(update, "👀", "en")
        self.assertEqual(msg.text_sent, ["Nice one, love it!"])


class FakeUser:
    def __init__(self, user_id=1, language_code="en"):
        self.id = user_id
        self.language_code = language_code
        self.username = "testuser"
        self.first_name = "Test"


class FakeUpdate:
    def __init__(self, message, user=None):
        self.message = message
        self.effective_user = user or FakeUser()


class FakePaxyo:
    """Stand-in for PaxyoClient with a fat balance.

    recent/schedules/due let tests seed the server-side memory: the
    user's last orders, active repeating orders, and due schedules.
    """

    RECENT_ORDER = {
        "id": 1827, "service_id": 1001,
        "service_name": "Instagram Followers | Fast",
        "link": "https://instagram.com/p/x", "quantity": 1000,
        "charge": 42.0, "status": "pending",
        "created_at": "2026-11-13T10:00:00Z",
    }

    DEPOSIT = {
        "id": "dep-1", "amount": 10, "method": "telebirr",
        "phone": "25199387383", "status": "pending",
        "created_at": "2026-11-13T11:00:00Z",
    }

    def __init__(self, balance=1000.0, recent=None, schedules=None, due=None,
                 deposit_none=False, deposit_error=None,
                 deposit_error_status=400,
                 payment_none=False, payment_error=None,
                 payment_error_status=502,
                 deposits=None, deposits_none=False, status="pending",
                 session=None, delayed=None, delayed_due=None,
                 delayed_none=False, claim_ok=True,
                 refills=None, refills_none=False, refills_live=False,
                 refill_stop_raises=False, refill_stop_409=False,
                 services=None, status_by_order=None, admin_stats=None,
                 my_referral=None, referral_error=None,
                 referral_error_status=400, referral_none=False,
                 referral_rows=None, balances=None,
                 ack_raise=False, ack_none=False,
                 cancel_refund_result=None, cancel_refund_error=None,
                 cancel_refund_results=None,
                 fail_refund_result=None, fail_refund_error=None,
                 next_order_ids=None, traits=None,
                 promo_codes=None, promo_none=False,
                 promo_redeem_result=None, promo_redeem_none=False,
                 promo_error=None, report_none=False, report_error=None,
                 ratings=None, ratings_none=False, rate_none=False,
                 rate_error=None, rate_already=False,
                 refill_result=None, refill_none=False,
                 refill_error=None,
                 price_snapshot=None, price_snapshot_none=False,
                 price_snapshot_error=None, price_snapshot_save_none=False,
                 price_snapshot_save_error=None, loyalty_result=None,
                 loyalty_error=None, feedback_asked_result=None,
                 feedback_asked_error=None, feedback_mark_none=False,
                 cancel_order_result=None, cancel_order_none=False,
                 cancel_order_error=None, partial_result=None,
                 partial_none=False, partial_error=None,
                 fraud_flags=None, fraud_none=False,
                 order_records=None, order_status_none=False,
                 split_cover_live=False, dripfeed_live=False,
                 prefs=None, reliability=None, pauses=None,
                 pause_result=None,
                 banned_ids=None, ban_none=False,
                 price_overrides=None, price_overrides_none=False):
        self._balance = balance
        self._status = status
        self._status_by_order = dict(status_by_order or {})
        self._admin_stats = admin_stats
        self.admin_stats_calls = 0
        self._my_referral = my_referral
        self._referral_error = referral_error
        self._referral_error_status = referral_error_status
        self._referral_none = referral_none
        # Referral rows the fake already holds: {telegram_id:
        # {"referrer": int, "code": str}} — first-wins, like the
        # server. Per-user balances for the deposit-bonus mirror.
        self._referral_rows = dict(referral_rows or {})
        self.balances = dict(balances or {})
        self._deposits_completed = set()
        self._referrer_bonus_paid = set()
        self._invitee_bonus_paid = set()
        self.referrals_recorded = []
        # Referral-bonus notify acks (16 Nov 2026): every
        # ack_referral_bonus call is recorded; ack_raise makes it
        # raise (server error), ack_none returns None (404: old
        # server without the endpoint).
        self.referral_bonus_acks = []
        self._ack_raise = ack_raise
        self._ack_none = ack_none
        self._services = list(services) if services is not None else SAMPLE_SERVICES
        self.orders_created = []
        self.order_keys = []
        # Second provider (15 Nov 2026): SMM orders go through
        # create_order_smm (POST /orders/smm) and are recorded
        # separately, so tests can tell which endpoint an order
        # went to. order_status_calls records (order_id,
        # telegram_id, provider) per status read.
        self.smm_orders_created = []
        self.order_status_calls = []
        # Stall rescue (15 Nov 2026): a seeded refund for
        # cancel_refund (None by default — the endpoint is not live
        # yet, so the real client returns None on its 404), a
        # record of every cancel-refund call, and optional ids for
        # orders create_order returns (1827 by default, so existing
        # tests keep their order id).
        self._cancel_refund_result = cancel_refund_result
        self._cancel_refund_error = cancel_refund_error
        # Per-order refund figures for rescue chains (price cap,
        # 15 Nov 2026): {"1841": {...refunded_etb 10.0...},
        # "1842": {...refunded_etb 5.0...}} — a chain refunds each
        # order's own stored total, not one figure for all.
        self._cancel_refund_results = dict(cancel_refund_results or {})
        self._next_order_ids = list(next_order_ids or [])
        self.cancel_refund_calls = []
        # Failed-order rescue (second provider, 15 Nov 2026): a
        # seeded refund for fail_refund (None by default — the
        # endpoint is not live yet, so the real client returns
        # None on its 404), a record of every fail-refund call,
        # and fail_refund_error=<status> raising the HTTP error
        # the real client raises (409 provider not failed, 502
        # provider did not answer).
        self._fail_refund_result = fail_refund_result
        self._fail_refund_error = fail_refund_error
        self.fail_refund_calls = []
        # Round 3 (15 Nov 2026): cancel order / partial refund /
        # fraud watch. cancel_order_none / partial_none mirror the
        # real client's 404 (endpoint not live yet); _error=409
        # returns the refusal passthrough (ok:false + the server's
        # reason); any other status raises the HTTP error the real
        # client raises. fraud_flags=None (default) returns an
        # empty flags list; fraud_none=True returns None (404).
        self._cancel_order_result = cancel_order_result
        self._cancel_order_none = cancel_order_none
        self._cancel_order_error = cancel_order_error
        self.cancel_order_calls = []
        self._partial_result = partial_result
        self._partial_none = partial_none
        self._partial_error = partial_error
        self.partial_refund_calls = []
        self._fraud_flags = fraud_flags
        self._fraud_none = fraud_none
        self.fraud_watch_calls = 0
        # Round 3 (15 Nov 2026): full order records for
        # order_status (cancel in chat needs service/total), and a
        # 404 mode (order_status_none) mirroring the real client's
        # None-on-404 for an unknown order id.
        self._order_records = dict(order_records or {})
        self._order_status_none = order_status_none
        # Split-test (15 Nov 2026): whether the server honours the
        # Paxyo cover (GET /split-cover/status) — False by default,
        # so tests prove the strict-cap behaviour until the endpoint
        # is "installed". order_split_kwargs / smm_order_split_kwargs
        # record the split kwargs of every order created (one dict
        # per order, only the kwargs actually passed, in creation
        # order), so tests can assert the markers and the cover.
        # Drip-feed (customizations #15, 15 Nov 2026): the same
        # shape for GET /orders/dripfeed-status.
        self._split_cover_live = split_cover_live
        self._dripfeed_live = dripfeed_live
        self.order_split_kwargs = []
        self.smm_order_split_kwargs = []
        # Per-customer prefs (customizations, 15 Nov 2026): the
        # seeded stored prefs (load_prefs returns them) and a
        # record of every save_prefs call, so tests can assert the
        # bot persists what the customer set.
        self._prefs = dict(prefs) if prefs is not None else None
        self.prefs_saved = []
        # Cancel-cutting (16 Nov 2026): the reliability map (GET
        # /service-reliability), the active pauses (GET
        # /service-pauses?active=1) and the pause-record reply
        # (POST /service-pause). All None by default — the
        # endpoints are not live yet, so the real client returns
        # None on their 404.
        self._reliability = (
            dict(reliability) if reliability is not None else None
        )
        self._pauses = list(pauses) if pauses is not None else None
        self._pause_result = pause_result
        self.record_service_cancel_calls = []
        self._services = list(services) if services is not None else SAMPLE_SERVICES
        # Ban + price overrides (19 Nov 2026).
        self._banned_ids = set(banned_ids or [])
        self._ban_none = ban_none
        self.ban_lookups = []
        self._price_overrides = list(price_overrides or [])
        self._price_overrides_none = price_overrides_none
        self.orders_created = []
        self.order_keys = []
        self._recent = list(recent) if recent is not None else []
        self._schedules = list(schedules) if schedules is not None else []
        self._due = list(due) if due is not None else []
        self.recurring_created = []
        self.recurring_cancelled = []
        self.recurring_paused = []
        self.recurring_ran = []
        self.deposits_created = []
        self._deposit_none = deposit_none
        self._deposit_error = deposit_error
        self._deposit_error_status = deposit_error_status
        # Payment start (owner, 17 Nov 2026): the bot exchanges
        # the popup token for the checkout right after Confirm —
        # payment_none=True returns None (the real client does
        # that on a 404), payment_error=<message> raises the HTTP
        # error the real client raises (status
        # payment_error_status, default 502). payment_starts
        # records every (deposit_id, token) call, so tests can
        # prove the exchange ran with the token only.
        self.payment_starts = []
        self._payment_none = payment_none
        self._payment_error = payment_error
        self._payment_error_status = payment_error_status
        # Deposit bundle (19 Nov 2026): the default fake is an
        # established user with 3 completed deposits, so the deposit
        # guide card does not gate flows that predate the guide.
        # Tests for new-user behaviour pass deposits=[] (or fewer
        # than 3 completed) explicitly.
        self._deposits = (
            list(deposits) if deposits is not None else [
                {"id": f"dep-old-{i}", "amount": 10,
                 "status": "completed",
                 "created_at": "2026-11-13T11:00:00Z"}
                for i in range(1, 4)
            ]
        )
        self._deposits_none = deposits_none
        self.deposit_status_checked = []
        # Session store (smart-loop round 1): a seeded session for
        # load_session, and a record of every save / confusion log.
        self._session = session
        self.session_loads = []
        self.sessions_saved = []
        self.confusions_logged = []
        # Per-user traits (feature 5, 15 Nov 2026): seeded traits
        # for load_traits (None = nothing stored yet, like the real
        # client's 404), and a record of every save / load / clear.
        self._traits = dict(traits) if traits is not None else None
        self.traits_saved = []
        self.traits_loads = []
        self.traits_cleared = []
        # One-time delayed orders (14 Nov 2026): a seeded list for
        # list_delayed_orders, due rows for due_delayed_orders, and
        # a record of every create / cancel / claim / finish.
        self._delayed = list(delayed) if delayed is not None else []
        self._delayed_due = list(delayed_due) if delayed_due is not None else []
        self._delayed_none = delayed_none
        self._claim_ok = claim_ok
        self._delayed_next_id = 101
        self.delayed_created = []
        self.delayed_cancelled = []
        self.delayed_claims = []
        self.delayed_finished = []
        # Auto-refill records (19 Nov 2026): a seeded list for
        # list_refills, and a record of every create / stop.
        # refills_none=True returns None from create_refill (the
        # real client does that on a 404: endpoint not live yet).
        # refills_live=False by default (like dripfeed_live):
        # the endpoint is not live in the fake's world unless a
        # test opts in.
        self._refills = list(refills) if refills is not None else []
        self._refills_none = refills_none
        self._refills_live = refills_live
        self._refill_next_id = 201
        self._refill_stop_raises = refill_stop_raises
        self._refill_stop_409 = refill_stop_409
        self.refills_created = []
        self.refills_stopped = []
        # Promo codes (ideas batch 2, feature 1, 15 Nov 2026):
        # promo_codes maps an uppercased code to its validate
        # record; an unmapped code gets the "does not exist"
        # record. promo_none=True returns None from validate and
        # redeem (the real client does that on a 404: endpoint not
        # live yet). promo_error=<status> raises the HTTP error the
        # real client raises on a non-404 failure.
        self._promo_codes = dict(promo_codes or {})
        self._promo_none = promo_none
        self._promo_redeem_result = promo_redeem_result
        self._promo_redeem_none = promo_redeem_none
        self._promo_error = promo_error
        self.promo_validates = []
        self.promo_redeems = []
        # Report a problem (ideas batch 2, feature 2, 15 Nov 2026):
        # reports_filed records every report (telegram_id, order_id,
        # message). report_none=True returns None (the real client
        # does that on a 404: endpoint not live yet, or the named
        # order is not this user's). report_error=<status> raises
        # the HTTP error the real client raises on a non-404
        # failure.
        self._report_none = report_none
        self._report_error = report_error
        self.reports_filed = []
        # Rate your order (ideas batch 2, feature 3, 15 Nov 2026):
        # ratings maps a service id (str) to {"good": n, "bad": n}
        # for service_ratings; unknown ids read 0/0. rate_none=True
        # returns None from rate_order (404: endpoint not live yet);
        # rate_error=<status> raises the HTTP error the real client
        # raises on a non-404 failure; rate_already=True returns the
        # already-rated 409 passthrough for every tap. ratings_none
        # returns None from service_ratings (404: endpoint not live).
        self._ratings = dict(ratings or {})
        self._ratings_none = ratings_none
        self._rate_none = rate_none
        self._rate_error = rate_error
        self._rate_already = rate_already
        self.ratings_filed = []
        self.ratings_calls = []
        # Refill in chat (15 Nov 2026, feature 3): a seeded refill
        # result for refill_order (None by default — the endpoint is
        # not live yet, so the real client returns None on its 404),
        # and a record of every refill call. refill_none=True
        # returns None (404: endpoint not live yet);
        # refill_error=<status> raises the HTTP error the real
        # client raises on a non-404 failure (409 not refillable
        # with the provider's reason, 501 refill action not
        # offered — the real client passes both bodies through as
        # {"ok": false, ...}, so this mirror returns the same dict
        # instead of raising for those two).
        self._refill_result = refill_result
        self._refill_none = refill_none
        self._refill_error = refill_error
        self.refill_calls = []
        # Provider price-change watch (feature 6, 15 Nov 2026):
        # price_snapshot seeds the stored snapshot ({} by default —
        # nothing stored yet, so the bot bootstraps); the save
        # REPLACES it, mirroring the server. price_snapshot_none
        # returns None from get (404: endpoint not live yet);
        # price_snapshot_error=<status> raises the HTTP error the
        # real client raises on a non-404 GET failure;
        # price_snapshot_save_none / _save_error do the same for
        # the POST. services_refresh_count is the catalogue
        # refresh counter the real client exposes — tests set it
        # by hand to simulate a real fetch.
        self._price_snapshot = dict(price_snapshot or {})
        self._price_snapshot_none = price_snapshot_none
        self._price_snapshot_error = price_snapshot_error
        self._price_snapshot_save_none = price_snapshot_save_none
        self._price_snapshot_save_error = price_snapshot_save_error
        self.price_snapshot_saved = []
        self.price_snapshot_calls = 0
        self.services_refresh_count = 0
        # Loyalty bonus (feature 9, 15 Nov 2026): loyalty_result
        # seeds the POST /loyalty/check reply (None by default —
        # the endpoint is not live yet, so the real client returns
        # None on its 404). loyalty_error=<status> raises the HTTP
        # error the real client raises on a non-404 failure.
        # loyalty_checks records every call.
        self._loyalty_result = loyalty_result
        self._loyalty_error = loyalty_error
        self.loyalty_checks = []
        # Feedback asked (feature 10, 15 Nov 2026):
        # feedback_asked_result seeds the GET /feedback/asked
        # reply (None by default — the endpoint is not live yet,
