class TestOnTextNeverSilent(unittest.IsolatedAsyncioTestCase):
    """A text message always gets a reply (19 Nov 2026): the first
    live drip request after a deploy went silent because the
    dripfeed probe raised out of handle_order_text and on_text
    had no safety net. on_voice already had one; on_text now
    does too."""

    def setUp(self):
        bot.SEEN_UPDATES.clear()

    def tearDown(self):
        bot.SEEN_UPDATES.clear()

    async def test_handler_exception_still_replies(self):
        msg = FakeMessage(text="place the order 10k views for every 1 hr")
        update = FakeUpdate(msg)
        with mock.patch.object(
            bot, "handle_order_text",
            new=mock.AsyncMock(side_effect=RuntimeError("boom")),
        ):
            await bot.on_text(update, None)
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("I did not understand", msg.text_sent[0])

    async def test_healthy_turn_is_untouched(self):
        # The net only catches failures: a healthy turn flows
        # through with no extra reply and no swallowed message.
        msg = FakeMessage(text="hello")
        update = FakeUpdate(msg)
        with mock.patch.object(
            bot, "handle_order_text",
            new=mock.AsyncMock(return_value=None),
        ) as flow:
            await bot.on_text(update, None)
        flow.assert_awaited_once()
        self.assertEqual(msg.text_sent, [])


class TestSchedules(unittest.IsolatedAsyncioTestCase):
    """List and stop repeating orders, by chat and by button."""

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()

    def _schedules(self):
        return [
            {"id": 7, "service_id": 1001,
             "service_name": "Instagram Followers | Fast",
             "link": "https://instagram.com/p/x", "quantity": 1000,
             "interval_minutes": 180},
            {"id": 8, "service_id": 1001,
             "service_name": "Instagram Followers | Fast",
             "link": "https://instagram.com/p/y", "quantity": 500,
             "interval_minutes": 1440},
        ]

    async def _send(self, text, intent, paxyo=None):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch("bot.extract_intent", new=mock.AsyncMock(return_value=intent)), \
             mock.patch("bot.paxyo", paxyo or FakePaxyo()), \
             mock.patch("bot.speak_reply"):
            await bot.handle_order_text(update, None, text)
        return msg

    async def _callback(self, data, paxyo=None):
        query = FakeQuery(data)
        update = FakeCallbackUpdate(query)
        with mock.patch("bot.paxyo", paxyo or FakePaxyo()):
            await bot.on_callback(update, None)
        return query

    async def test_schedules_intent_lists_them(self):
        msg = await self._send(
            "what is repeating", intent_of("schedules"),
            paxyo=FakePaxyo(schedules=self._schedules()),
        )
        self.assertIn("Instagram Followers", msg.text_sent[0])
        self.assertNotIn("Instagram Followers | Fast", msg.text_sent[0])
        self.assertIn("every 3 hours", msg.text_sent[0])
        self.assertIn("every 1 day", msg.text_sent[0])

    async def test_schedules_intent_with_none(self):
        msg = await self._send(
            "what is repeating", intent_of("schedules"),
            paxyo=FakePaxyo(schedules=[]),
        )
        self.assertEqual(msg.text_sent, ["You have no repeating orders."])

    async def test_schedules_command_lists_them(self):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch("bot.paxyo", FakePaxyo(schedules=self._schedules())):
            await bot.schedules_cmd(update, None)
        self.assertIn("Instagram Followers", msg.text_sent[0])
        self.assertNotIn("Instagram Followers | Fast", msg.text_sent[0])

    async def test_stop_with_one_schedule_cancels_it(self):
        paxyo = FakePaxyo(schedules=self._schedules()[:1])
        msg = await self._send(
            "stop the repeating order", intent_of("stop_schedule"),
            paxyo=paxyo,
        )
        self.assertEqual(paxyo.recurring_cancelled, [7])
        self.assertEqual(
            msg.text_sent,
            ["Stopped the repeating order for Instagram Followers."],
        )

    async def test_stop_with_several_asks_which(self):
        paxyo = FakePaxyo(schedules=self._schedules())
        msg = await self._send(
            "stop the repeating order", intent_of("stop_schedule"),
            paxyo=paxyo,
        )
        self.assertEqual(paxyo.recurring_cancelled, [])
        self.assertEqual(
            msg.text_sent, ["Which repeating order do you want to stop?"]
        )
        self.assertIsNotNone(msg.markups[0])  # stop buttons

    async def test_stop_button_cancels_that_schedule(self):
        paxyo = FakePaxyo(schedules=self._schedules())
        query = await self._callback("stoprec:8", paxyo=paxyo)
        self.assertEqual(paxyo.recurring_cancelled, [8])
        self.assertEqual(
            query.edited,
            ["Stopped the repeating order for Instagram Followers."],
        )

    async def test_cancel_with_both_pending_and_schedules_asks_which(self):
        bot.PENDING["abc123"] = make_pending()
        paxyo = FakePaxyo(schedules=self._schedules()[:1])
        msg = await self._send("cancel", intent_of("cancel"), paxyo=paxyo)
        self.assertEqual(msg.text_sent, ["Which one do you want to stop?"])
        self.assertIsNotNone(msg.markups[0])  # This order + schedule buttons
        self.assertEqual(len(bot.PENDING), 1)  # nothing stopped yet


class FakeChat:
    """Stand-in for a Telegram Chat as get_chat returns it."""

    def __init__(self, first_name="Test", username="testuser"):
        self.first_name = first_name
        self.username = username


class FakeBot:
    """Stand-in for the Telegram Bot: records messages the scheduler
    sends to users."""

    def __init__(self):
        self.sent = []
        self.sent_markups = []
        self.chat = FakeChat()

    async def send_message(self, chat_id, text, reply_markup=None):
        self.sent.append((chat_id, text))
        self.sent_markups.append(reply_markup)

    async def get_chat(self, chat_id):
        return self.chat


class FakeApp:
    def __init__(self):
        self.bot = FakeBot()


def due_schedule(**overrides):
    sched = {
        "id": 7, "user_id": 1, "service_id": 1001,
        "service_name": "Instagram Followers | Fast",
        "link": "https://instagram.com/p/x", "quantity": 1000,
        "interval_minutes": 180, "next_run_at": "2026-11-13T15:00:00Z",
    }
    sched.update(overrides)
    return sched


def due_delayed(**overrides):
    """A scheduled delayed order whose run_at is in the past (due).
    run_at is MySQL DATETIME format, as the server stores it."""
    item = {
        "id": 11, "telegram_id": 1, "service_id": 1001,
        "link": "https://instagram.com/p/x", "quantity": 1000,
        "total": 42.0, "run_at": "2026-11-13 15:00:00",
        "status": "scheduled", "idempotency_key": "delay-abc123",
        "created_at": "2026-11-13T12:00:00Z",
    }
    item.update(overrides)
    return item


class TestSchedulerLoop(unittest.IsolatedAsyncioTestCase):
    """The 60-second loop: due schedules run once, balance is checked
    first, and a schedule that slept only ever runs once on wake."""

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot.BIG_DEPOSIT_ALERTED.clear()
        bot.FEEDBACK_ASKED.clear()
        bot.FEEDBACK_PENDING.clear()
        bot._PRICE_WATCH_LAST_REFRESH = None
        bot._PRICE_WATCH_OFF = False
        bot._PROVIDER_BALANCE_LAST_CHECK = -1e9  # long ago even on a fresh VM (monotonic starts at 0)
        bot._PROVIDER_BALANCE_STATE = "ok"

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot.BIG_DEPOSIT_ALERTED.clear()
        bot.FEEDBACK_ASKED.clear()
        bot.FEEDBACK_PENDING.clear()
        bot._PRICE_WATCH_LAST_REFRESH = None
        bot._PRICE_WATCH_OFF = False
        bot._PROVIDER_BALANCE_LAST_CHECK = -1e9  # long ago even on a fresh VM (monotonic starts at 0)
        bot._PROVIDER_BALANCE_STATE = "ok"

    async def test_due_schedule_places_one_order_and_notifies(self):
        paxyo = FakePaxyo(due=[due_schedule()])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
        self.assertEqual(len(paxyo.orders_created), 1)
        self.assertEqual(paxyo.orders_created[0], (1001, "https://instagram.com/p/x", 1000))
        self.assertEqual(paxyo.recurring_ran, [(7, 1, 1827)])
        self.assertEqual(len(app.bot.sent), 1)
        self.assertEqual(app.bot.sent[0][0], 1)
        self.assertIn("Order placed!", app.bot.sent[0][1])
        self.assertIn("1827", app.bot.sent[0][1])

    async def test_catch_up_runs_once_not_per_missed_interval(self):
        # The process slept for hours: next_run_at is far in the past.
        # The schedule still runs exactly once this cycle.
        paxyo = FakePaxyo(due=[due_schedule(next_run_at="2026-11-13T05:00:00Z")])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
            await bot.run_scheduler_cycle(app)  # second cycle, same slot
        self.assertEqual(len(paxyo.orders_created), 1)
        self.assertEqual(len(paxyo.order_keys), 1)
        self.assertEqual(paxyo.order_keys[0], "rec-7-2026-11-13T05:00:00Z")

    async def test_balance_short_pauses_and_notifies_no_order(self):
        paxyo = FakePaxyo(balance=10.0, due=[due_schedule()])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
        self.assertEqual(paxyo.orders_created, [])
        self.assertEqual(paxyo.recurring_paused, [7])
        self.assertEqual(paxyo.recurring_ran, [])
        self.assertEqual(len(app.bot.sent), 1)
        self.assertIn("Paused", app.bot.sent[0][1])
        self.assertIn("paxyo.et", app.bot.sent[0][1])

    async def test_order_failure_retries_next_cycle_without_spam(self):
        class FailingPaxyo(FakePaxyo):
            async def create_order(self, *args, **kwargs):
                raise RuntimeError("provider down")

        paxyo = FailingPaxyo(due=[due_schedule()])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
            await bot.run_scheduler_cycle(app)  # retries, still failing
        self.assertEqual(paxyo.recurring_ran, [])
        self.assertEqual(paxyo.orders_created, [])
        # One message per failed cycle at most — two cycles, two notes.
        self.assertEqual(len(app.bot.sent), 2)
        self.assertIn("try again next round", app.bot.sent[0][1])

    async def test_unknown_service_is_skipped_quietly(self):
        paxyo = FakePaxyo(due=[due_schedule(service_id=9999)])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
        self.assertEqual(paxyo.orders_created, [])
        self.assertEqual(app.bot.sent, [])

    async def test_no_due_schedules_does_nothing(self):
        paxyo = FakePaxyo(due=[])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
        self.assertEqual(paxyo.orders_created, [])
        self.assertEqual(app.bot.sent, [])

    async def test_due_fetch_failure_never_raises(self):
        class BrokenPaxyo(FakePaxyo):
            async def due_recurring(self):
                raise RuntimeError("api down")

        app = FakeApp()
        with mock.patch("bot.paxyo", BrokenPaxyo()):
            await bot.run_scheduler_cycle(app)  # must not raise
        self.assertEqual(app.bot.sent, [])


class TestDelayedOrders(unittest.IsolatedAsyncioTestCase):
    """One-time delayed orders (14 Nov 2026): "order 10k views to
    this link after 3 hrs" builds a draft, shows a Confirm card with
    the scheduled time in EAT, and places ONCE at that time — even
    after a restart, even if the user is asleep. Nothing is
    scheduled until Confirm."""

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.PENDING_DELAYED.clear()
        bot.DELAYED_DRAFT.clear()
        bot.DELAYED_MEMORY.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.PENDING_DELAYED.clear()
        bot.DELAYED_DRAFT.clear()
        bot.DELAYED_MEMORY.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()

    async def _send(self, text, intent, paxyo=None):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch("bot.extract_intent", new=mock.AsyncMock(return_value=intent)), \
             mock.patch("bot.paxyo", paxyo or FakePaxyo()), \
             mock.patch("bot.speak_reply"):
            await bot.handle_order_text(update, None, text)
        return msg

    async def _callback(self, data, paxyo=None):
        query = FakeQuery(data)
        update = FakeCallbackUpdate(query)
        with mock.patch("bot.paxyo", paxyo or FakePaxyo()):
            await bot.on_callback(update, None)
        return query

    async def _extract(self, payload):
        """extract_intent with the AI mocked to return `payload`."""
        with mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(return_value=json.dumps(payload)),
        ):
            return await bot.extract_intent("test message")

    def _delayed_intent(self):
        return delayed_intent(
            platform="instagram", service_hint="followers",
            link="https://instagram.com/p/x", quantity=1000,
            delay_minutes=180,
        )

    def _delayed_list(self):
        return [
            due_delayed(),
            due_delayed(id=12, link="https://instagram.com/p/y",
                        quantity=500),
        ]

    # (1) Delay parsing ------------------------------------------------

    def test_parse_delay_minutes(self):
        cases = {
            "order 10k views to this link after 3 hrs": 180,
            "in 2 hours": 120,
            "after 30 minutes": 30,
            "in 45 mins": 45,
            "after 1 hour 30 minutes": 90,
            "after 2 days": 2880,
            "after three hours": 180,
            "in forty five minutes": 45,
        }
        for text, expected in cases.items():
            with self.subTest(text=text):
                self.assertEqual(bot.parse_delay_minutes(text), expected)

    def test_parse_delay_minutes_rejects_non_delays(self):
        for text in (
            "order 1k views every 3 hours",  # recurring, not delayed
            "order 1k views",
            "in the morning",
            "after 0 hours",
            "after I pay",
            "",
        ):
            with self.subTest(text=text):
                self.assertIsNone(bot.parse_delay_minutes(text))

    def test_delayed_run_at_and_eat_format(self):
        now = datetime.now(timezone.utc)
        run_at = bot.delayed_run_at_iso(180)
        run = datetime.strptime(run_at, "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
        self.assertAlmostEqual(
            (run - now).total_seconds(), 180 * 60, delta=120
        )
        # "HH:MM EAT" today, or "HH:MM EAT tomorrow" past midnight.
        self.assertIn("EAT", bot.format_eat_run_at(run_at))
        # Tomorrow noon EAT is always "tomorrow", whatever the hour.
        eat_now = datetime.now(timezone.utc).astimezone(bot.EAT_TZ)
        tomorrow_noon = (eat_now + timedelta(days=1)).replace(
            hour=12, minute=0, second=0, microsecond=0
        )
        run_at_tomorrow = tomorrow_noon.astimezone(timezone.utc).strftime(
            "%Y-%m-%d %H:%M:%S"
        )
        self.assertIn("tomorrow", bot.format_eat_run_at(run_at_tomorrow))
        self.assertEqual(bot.format_eat_run_at("not a time"), "not a time")

    # (2) Local intent + strict extraction ----------------------------

    def test_local_intent_reads_delayed_order(self):
        out = bot.local_intent("order 10k views to this link after 3 hrs")
        self.assertEqual(out["intent"], "delayed_order")
        self.assertEqual(out["delay_minutes"], 180)
        self.assertEqual(out["quantity"], 10000)

