        self.assertEqual(
            bot.local_intent("my scheduled orders")["intent"],
            "delayed_orders",
        )
        self.assertEqual(
            bot.local_intent("cancel my scheduled order")["intent"],
            "cancel_delayed",
        )
        self.assertEqual(
            bot.local_intent("show my delayed orders")["intent"],
            "delayed_orders",
        )

