    async def test_due_delayed_places_one_order_and_notifies(self):
        paxyo = FakePaxyo(delayed_due=[due_delayed()])
        app = FakeApp()
        with mock.patch("bot.paxyo", paxyo):
            await bot.run_scheduler_cycle(app)
