class TestProbeEndpoints(unittest.IsolatedAsyncioTestCase):
    """The optional-endpoint probes (GET /split-cover/status,
    GET /orders/dripfeed-status) never raise into a chat: any
    failure means "not live" (19 Nov 2026: the dripfeed probe
    raised on a non-404 failure and the first live drip request
    after a deploy got no reply at all)."""

    def _probe_request(self):
        return bot.httpx.Request(
            "GET", "https://paxyo.et/api/bot/orders/dripfeed-status")

    async def test_dripfeed_live_http_500_returns_false_and_caches(self):
        client = bot.PaxyoClient()
        try:
            req = self._probe_request()
            err = bot.httpx.HTTPStatusError(
                "server error", request=req,
                response=bot.httpx.Response(500, request=req))
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=err)
            ) as send:
                self.assertIs(await client.dripfeed_live(), False)
                self.assertIs(await client.dripfeed_live(), False)
            self.assertEqual(send.call_count, 1)
        finally:
            await client._client.aclose()

    async def test_dripfeed_live_non_json_body_returns_false(self):
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=(
                    json.JSONDecodeError("Expecting value", "<html>", 0)))
            ):
                self.assertIs(await client.dripfeed_live(), False)
        finally:
            await client._client.aclose()

    async def test_dripfeed_live_connect_error_returns_false(self):
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=(
                    bot.httpx.ConnectError(
                        "connection refused", request=self._probe_request())))
            ):
                self.assertIs(await client.dripfeed_live(), False)
        finally:
            await client._client.aclose()

    async def test_dripfeed_live_404_returns_false(self):
        client = bot.PaxyoClient()
        try:
            req = self._probe_request()
            err = bot.httpx.HTTPStatusError(
                "not found", request=req,
                response=bot.httpx.Response(404, request=req))
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=err)
            ):
                self.assertIs(await client.dripfeed_live(), False)
        finally:
            await client._client.aclose()

    async def test_dripfeed_live_true_when_endpoint_answers(self):
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(
                    return_value={"ok": True, "dripfeed_live": True}),
            ):
                self.assertIs(await client.dripfeed_live(), True)
        finally:
            await client._client.aclose()

    async def test_dripfeed_live_false_expires_then_install_is_picked_up(self):
        # 19 Nov 2026: a False answer was cached forever per
        # process, so installing api-order-dripfeed.php on the
        # server changed nothing until the next deploy. A False
        # answer must expire after DRIPFEED_LIVE_CACHE_SECONDS
        # and the probe must run again.
        client = bot.PaxyoClient()
        try:
            req = self._probe_request()
            err = bot.httpx.HTTPStatusError(
                "not found", request=req,
                response=bot.httpx.Response(404, request=req))
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(side_effect=err),
            ) as send:
                self.assertIs(await client.dripfeed_live(), False)
                self.assertIs(await client.dripfeed_live(), False)
                self.assertEqual(send.call_count, 1)
            client._dripfeed_live_at = -1e9  # expire the cache
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(
                    return_value={"ok": True, "dripfeed_live": True}),
            ) as send:
                self.assertIs(await client.dripfeed_live(), True)
                self.assertEqual(send.call_count, 1)
        finally:
            await client._client.aclose()

    async def test_dripfeed_live_true_expires_then_reprobes(self):
        # A True answer also expires, so a server that goes
        # down again is not promised forever.
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(
                    return_value={"ok": True, "dripfeed_live": True}),
            ):
                self.assertIs(await client.dripfeed_live(), True)
            client._dripfeed_live_at = -1e9  # expire the cache
            req = self._probe_request()
            err = bot.httpx.HTTPStatusError(
                "not found", request=req,
                response=bot.httpx.Response(404, request=req))
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=err),
            ):
                self.assertIs(await client.dripfeed_live(), False)
        finally:
            await client._client.aclose()

    async def test_split_cover_live_http_500_returns_false(self):
        client = bot.PaxyoClient()
        try:
            req = bot.httpx.Request(
                "GET", "https://paxyo.et/api/bot/split-cover/status")
            err = bot.httpx.HTTPStatusError(
                "server error", request=req,
                response=bot.httpx.Response(500, request=req))
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=err)
            ):
                self.assertIs(await client.split_cover_live(), False)
        finally:
            await client._client.aclose()


class TestPromoCodesApiClient(unittest.IsolatedAsyncioTestCase):
    """POST /promo-codes/validate and /promo-codes/redeem: request
    shape, the 404 -> None mapping, and the business-failure
    passthrough (ok:false is an HTTP 200 the client must return,
    never raise). Also that a validated code rides on the deposit
    create body — and that no code means no promo_code key at all."""

    def _err(self, status):
        req = bot.httpx.Request("POST", "https://paxyo.et/api/bot/promo-codes/validate")
        resp = bot.httpx.Response(status, request=req)
        return bot.httpx.HTTPStatusError("error", request=req, response=resp)

    async def test_validate_404_returns_none(self):
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send", new=mock.AsyncMock(side_effect=self._err(404))
            ):
                self.assertIsNone(await client.validate_promo(1, "PAXYO20"))
        finally:
            await client._client.aclose()

    async def test_validate_posts_expected_body_and_returns_record(self):
        client = bot.PaxyoClient()
        try:
            record = {"ok": True, "percent": 20,
                      "message": "Promo code valid: 20% bonus on your deposit.",
                      "already_used": False}
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(return_value=record),
            ) as send:
                result = await client.validate_promo(1, "PAXYO20")
            self.assertEqual(result, record)
            request = send.call_args.args[0]
            self.assertEqual(request.method, "POST")
            self.assertTrue(request.url.path.endswith("/promo-codes/validate"))
            self.assertEqual(request.headers["X-Bot-Secret"], "test-secret")
            self.assertEqual(
                json.loads(request.content),
                {"telegram_id": 1, "code": "PAXYO20"},
            )
        finally:
            await client._client.aclose()

    async def test_validate_passes_business_failure_through(self):
        # Already-used is ok:false with already_used:true on HTTP
        # 200 — a plain answer for the user, not an exception.
        client = bot.PaxyoClient()
        try:
            record = {"ok": False, "percent": None,
                      "message": "You have already used this code.",
                      "already_used": True}
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(return_value=record),
            ):
                result = await client.validate_promo(1, "PAXYO20")
            self.assertEqual(result, record)
            self.assertFalse(result["ok"])
            self.assertTrue(result["already_used"])
        finally:
            await client._client.aclose()

    async def test_validate_invalid_passes_through(self):
        client = bot.PaxyoClient()
