class TestGeminiRetry(unittest.IsolatedAsyncioTestCase):
    """_gemini_post fails fast on HTTP errors (fast failover,
    17 Nov 2026), and gemini_* use it."""

    def _status_error(self, status):
        req = bot.httpx.Request("POST", "https://example.com/gemini")
        resp = bot.httpx.Response(status, request=req)
        return bot.httpx.HTTPStatusError(f"{status}", request=req, response=resp)

    def _ok_response(self, text="hello"):
        return FakeCloudTTSResponse({
            "candidates": [{"content": {"parts": [{"text": text}]}}]
        })

    async def test_generate_fails_fast_on_429(self):
        # Fast failover (17 Nov 2026): a 429 raises at once — no
        # retry, no sleep — so ai_generate falls through at once.
        client = FlakyClient([self._status_error(429)])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            with self.assertRaises(bot.httpx.HTTPStatusError):
                await bot.gemini_generate("hi")
        self.assertEqual(len(client.posts), 1)
        sleep_mock.assert_not_awaited()

    async def test_generate_raises_after_one_429(self):
        client = FlakyClient([self._status_error(429)] * 3)
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            with self.assertRaises(bot.httpx.HTTPStatusError):
                await bot.gemini_generate("hi")
        self.assertEqual(len(client.posts), 1)
        sleep_mock.assert_not_awaited()

    async def test_transcribe_fails_fast_on_503(self):
        client = FlakyClient([self._status_error(503)])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            with self.assertRaises(bot.httpx.HTTPStatusError):
                await bot.gemini_transcribe(b"fake-ogg")
        self.assertEqual(len(client.posts), 1)
        sleep_mock.assert_not_awaited()

    async def test_transcribe_uses_longer_media_timeout(self):
        # Owner, 18 Nov 2026: Gemini transcription failed with a
        # transport error on THREE consecutive voice notes while
        # text calls on the same 5s budget succeeded — the 5s read
        # timeout fires on an audio upload + multimodal
        # processing. Transcription gets the 30s media budget.
        client = FlakyClient([self._ok_response("ሰላም")])
        with mock.patch("bot.httpx.AsyncClient", return_value=client) as mocked, \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()):
            self.assertEqual(await bot.gemini_transcribe(b"fake-ogg"), "ሰላም")
        mocked.assert_called_once_with(
            timeout=bot.GEMINI_MEDIA_TIMEOUT_SECONDS, trust_env=False
        )

    async def test_vision_uses_longer_media_timeout(self):
        # A photo upload is the same shape as an audio upload, so
        # vision gets the media budget too, not the 5s text budget.
        client = FlakyClient([self._ok_response("{\"summary\": \"x\"}")])
        with mock.patch("bot.httpx.AsyncClient", return_value=client) as mocked, \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()):
            self.assertEqual(
                await bot.gemini_vision(b"fake-jpeg"), "{\"summary\": \"x\"}"
            )
        mocked.assert_called_once_with(
            timeout=bot.GEMINI_MEDIA_TIMEOUT_SECONDS, trust_env=False
        )

    async def test_generate_keeps_five_second_timeout(self):
        # Text calls keep the 5s budget: the fast-failover
        # guarantee for chat replies depends on it.
        client = FlakyClient([self._ok_response()])
        with mock.patch("bot.httpx.AsyncClient", return_value=client) as mocked, \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()):
            self.assertEqual(await bot.gemini_generate("hi"), "hello")
        mocked.assert_called_once_with(
            timeout=bot.AI_POST_TIMEOUT_SECONDS, trust_env=False
        )

    async def test_transcribe_slow_response_succeeds_on_media_budget(self):
        # A response that arrives after 5s — too slow for the old
        # budget — succeeds with the media budget. The fake client
        # times out when its timeout is the old 5s and answers
        # when it is the media budget; the old budget still fails
        # outright, which is the live failure being fixed.
        class _TimeoutAwareClient:
            def __init__(self, timeout, trust_env=False):
                self.timeout = timeout
                self.posts = []

            async def __aenter__(self):
                return self

            async def __aexit__(self, *exc):
                return False

            async def post(self, url, params=None, json=None):
                self.posts.append({"url": url, "params": params, "json": json})
                if self.timeout < bot.GEMINI_MEDIA_TIMEOUT_SECONDS:
                    raise bot.httpx.TimeoutException(
                        "timed out",
                        request=bot.httpx.Request("POST", url),
                    )
                return FakeCloudTTSResponse({
                    "candidates": [{"content": {"parts": [
                        {"text": "ሰላም"}]}}]
                })

        with mock.patch("bot.httpx.AsyncClient", new=_TimeoutAwareClient), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()):
            self.assertEqual(
                await bot.gemini_transcribe(b"fake-ogg"), "ሰላም"
            )
        with mock.patch("bot.httpx.AsyncClient", new=_TimeoutAwareClient), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()):
            with self.assertRaises(bot.httpx.TimeoutException):
                await bot._gemini_post({"contents": []})


class TestFastFailover(unittest.IsolatedAsyncioTestCase):
    """Fast failover (owner, 17 Nov 2026): an HTTP error raises at
    once so ai_generate falls through to the next provider with no
    retry delay; only a transport failure gets one quick retry;
    every provider call is bounded by AI_POST_TIMEOUT_SECONDS."""

    def _status_error(self, status):
        req = bot.httpx.Request(
            "POST", "https://api.groq.com/openai/v1/chat/completions"
        )
        resp = bot.httpx.Response(status, request=req)
        return bot.httpx.HTTPStatusError(f"{status}", request=req, response=resp)

    def _transport_error(self, kind):
        req = bot.httpx.Request(
            "POST", "https://api.groq.com/openai/v1/chat/completions"
        )
        if kind == "timeout":
            return bot.httpx.TimeoutException("timed out", request=req)
        return bot.httpx.ConnectError("connection refused", request=req)

    def _ok_response(self, text="hello"):
        return FakeCloudTTSResponse({
            "choices": [{"message": {"content": text}}]
        })

    async def test_timeout_retries_once_then_succeeds(self):
        # A timeout is a transport failure: one quick retry after
        # 0.5s, then the reply lands.
        client = GroqFlakyClient(
            [self._transport_error("timeout"), self._ok_response()]
        )
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            self.assertEqual(await bot.groq_generate("hi"), "hello")
        self.assertEqual(len(client.posts), 2)
        sleep_mock.assert_awaited_once_with(
            bot.AI_TRANSIENT_RETRY_DELAY_SECONDS
        )

    async def test_connect_error_retries_once_then_succeeds(self):
        client = GroqFlakyClient(
            [self._transport_error("connect"), self._ok_response()]
        )
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", "sk-deepseek-test"), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            self.assertEqual(await bot.deepseek_generate("hi"), "hello")
        self.assertEqual(len(client.posts), 2)
        sleep_mock.assert_awaited_once_with(
            bot.AI_TRANSIENT_RETRY_DELAY_SECONDS
        )

    async def test_timeout_twice_raises_after_one_retry(self):
        client = GroqFlakyClient(
            [self._transport_error("timeout")] * 2
        )
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            with self.assertRaises(bot.httpx.TimeoutException):
                await bot.groq_generate("hi")
        self.assertEqual(len(client.posts), 2)
        sleep_mock.assert_awaited_once_with(
            bot.AI_TRANSIENT_RETRY_DELAY_SECONDS
        )

    async def test_http_500_fails_fast_with_no_retry(self):
        client = GroqFlakyClient([self._status_error(500)])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            with self.assertRaises(bot.httpx.HTTPStatusError):
                await bot.groq_generate("hi")
        self.assertEqual(len(client.posts), 1)
        sleep_mock.assert_not_awaited()

    async def test_post_uses_bounded_timeout(self):
        # One provider call may take at most AI_POST_TIMEOUT_SECONDS
        # (was 120s): a hung provider cannot eat the reply budget.
        client = GroqFlakyClient([self._ok_response()])
        with mock.patch("bot.httpx.AsyncClient", return_value=client) as mocked, \
             mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"):
            self.assertEqual(await bot.groq_generate("hi"), "hello")
        mocked.assert_called_once_with(
            timeout=bot.AI_POST_TIMEOUT_SECONDS, trust_env=False
        )

    async def test_ai_generate_falls_through_at_once_on_groq_429(self):
        # The reported bug, end to end: Groq 429s on its daily
        # limit and DeepSeek answers — with no retry sleep in
        # between (the old shape paid 5s + 15s first).
        client = GroqFlakyClient([self._status_error(429)])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", "sk-deepseek-test"), \
             mock.patch(
                 "bot.deepseek_generate",
                 new=mock.AsyncMock(return_value="d"),
             ), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            self.assertEqual(await bot.ai_generate("hello"), "d")
        self.assertEqual(len(client.posts), 1)
        sleep_mock.assert_not_awaited()


class TestAiTimingLogs(unittest.IsolatedAsyncioTestCase):
    """Timing logs (owner, 17 Nov 2026): every ai_generate attempt
    logs provider + seconds on success and on failure, plus the
    total — and never logs a secret (no URL, no key, no prompt, no
    reply)."""

    def _key_url_error(self, status, url):
        req = bot.httpx.Request("POST", url)
        resp = bot.httpx.Response(status, request=req)
        return bot.httpx.HTTPStatusError(
            f"{status}", request=req, response=resp
        )

    def _status_error(self, status):
        req = bot.httpx.Request(
            "POST", "https://api.groq.com/openai/v1/chat/completions"
        )
        resp = bot.httpx.Response(status, request=req)
        return bot.httpx.HTTPStatusError(f"{status}", request=req, response=resp)

    async def test_groq_success_logs_provider_seconds_and_total(self):
        with mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch(
                 "bot.groq_generate",
                 new=mock.AsyncMock(return_value="ok"),
             ), \
             self.assertLogs("paxorder_bot", level="INFO") as logs:
            self.assertEqual(await bot.ai_generate("hello"), "ok")
        joined = "\n".join(logs.output)
        self.assertRegex(joined, r"ai Groq ok \d+\.\d\ds")
        self.assertRegex(joined, r"ai_generate ok \d+\.\d\ds")

    async def test_groq_429_logs_failure_status_and_total(self):
        client = GroqFlakyClient([self._status_error(429)])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", "<redacted>"), \
             mock.patch(
                 "bot.deepseek_generate",
                 new=mock.AsyncMock(return_value="d"),
             ), \
             self.assertLogs("paxorder_bot", level="INFO") as logs:
            self.assertEqual(await bot.ai_generate("hello"), "d")
        joined = "\n".join(logs.output)
        # The failure warning keeps its exact old format (existing
        # secrecy tests assert the "(HTTP 429)" substring); the
        # seconds live on their own info line.
        self.assertIn(
            "Groq generate failed, trying next provider (HTTP 429)",
            joined,
        )
        self.assertRegex(joined, r"ai Groq failed \d+\.\d\ds")
        self.assertRegex(joined, r"ai_generate ok \d+\.\d\ds")

    async def test_total_time_logged_when_every_provider_fails(self):
        with mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", "<redacted>"), \
             mock.patch(
                 "bot.groq_generate",
                 new=mock.AsyncMock(side_effect=RuntimeError("down")),
             ), \
             mock.patch(
                 "bot.deepseek_generate",
                 new=mock.AsyncMock(side_effect=RuntimeError("down")),
             ), \
             mock.patch(
                 "bot.kilo_generate",
                 new=mock.AsyncMock(side_effect=RuntimeError("down")),
             ), \
             self.assertLogs("paxorder_bot", level="INFO") as logs:
            with self.assertRaises(RuntimeError):
                await bot.ai_generate("hello")
        joined = "\n".join(logs.output)
        for provider in ("Groq", "DeepSeek", "Kilo"):
            self.assertIn(
                f"{provider} generate failed, trying next provider",
                joined,
            )
            self.assertRegex(
                joined, rf"ai {provider} failed \d+\.\d\ds"
            )
        self.assertRegex(joined, r"ai_generate failed \d+\.\d\ds")

    async def test_attempt_log_never_carries_secrets(self):
        # The Gemini URL carries the API key (?key=...) and leaked
        # into the Render logs on 13 Nov 2026: a failure log must
        # carry the status only, and a success log must not carry
        # the reply text.
        err = self._key_url_error(
            429,
            "https://generativelanguage.googleapis.com/v1beta/models/"
            "gemini-3.5-flash:generateContent?key=FAKESECRETKEY",
        )

        async def _raise():
            raise err

        with self.assertLogs("paxorder_bot", level="INFO") as logs:
            with self.assertRaises(bot.httpx.HTTPStatusError):
                await bot._ai_attempt("Gemini", _raise())
        joined = "\n".join(logs.output)
        self.assertIn(
            "Gemini generate failed, trying next provider (HTTP 429)",
            joined,
        )
        self.assertRegex(joined, r"ai Gemini failed \d+\.\d\ds")
        self.assertNotIn("key=", joined)
        self.assertNotIn("FAKESECRETKEY", joined)
        self.assertNotIn("generateContent", joined)
        self.assertNotIn("Bearer ", joined)

        async def _ok():
            return "SECRET-REPLY-TEXT"

        with self.assertLogs("paxorder_bot", level="INFO") as logs:
            self.assertEqual(
                await bot._ai_attempt("Groq", _ok()), "SECRET-REPLY-TEXT"
            )
        joined = "\n".join(logs.output)
        self.assertRegex(joined, r"ai Groq ok \d+\.\d\ds")
        self.assertNotIn("SECRET-REPLY-TEXT", joined)


class TestSimpleChatFastPath(unittest.IsolatedAsyncioTestCase):
    """One AI call for simple chats (owner, 17 Nov 2026): a plain
    greeting or a question about Paxyo itself skips the AI classify
    call — the local reader pins it down — so the turn costs one AI
    call (paxyo_info, how_to) or none (greeting, help,
    how_to_order). Anything that could be an order, money or state
    still goes through the classifier."""

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()

    async def _send_counting(self, text, ai_side_effect):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        ai_mock = mock.AsyncMock(side_effect=ai_side_effect)
        with mock.patch("bot.ai_generate", ai_mock), \
             mock.patch("bot.paxyo", FakePaxyo()), \
             mock.patch("bot.speak_reply") as speak:
            await bot.handle_order_text(update, None, text)
        self.assertEqual(msg.voice_sent, [])
        speak.assert_not_called()
        return msg, ai_mock

    def test_greeting_intent(self):
        intent = bot.simple_chat_intent("Hello")
        self.assertEqual(intent["intent"], "greeting")
        self.assertNotIn("gemini_failed", intent)

    def test_services_question_intent(self):
        for text in (
            "What services do you offer?",
            "Hello, what services do you offer?",
            "What is Paxyo?",
            "How long does delivery take?",
        ):
            intent = bot.simple_chat_intent(text)
            self.assertIsNotNone(intent, text)
            self.assertEqual(intent["intent"], "paxyo_info", text)

    def test_help_and_how_to_intents(self):
        self.assertEqual(
            bot.simple_chat_intent("help")["intent"], "help"
        )
        self.assertEqual(
            bot.simple_chat_intent("How do I order?")["intent"],
            "how_to_order",
        )
        self.assertEqual(
            bot.simple_chat_intent("How do I make my account public?")["intent"],
            "how_to",
        )

    def test_order_deposit_and_state_messages_not_skipped(self):
        for text in (
            "I want 1000 Instagram followers https://instagram.com/p/x",
            "I want to deposit 10 ETB",
            "How much is my balance",
            "Cancel my order",
            "What services do you offer? I want a refund",
            "1000",
            "Hello, I want 1000 TikTok views",
            "What is the weather like?",
        ):
            self.assertIsNone(bot.simple_chat_intent(text), text)

    async def test_greeting_costs_zero_ai_calls(self):
        msg, ai_mock = await self._send_counting("Hello", [])
        ai_mock.assert_not_called()
        self.assertIn("Tell me the service you want", msg.text_sent[0])

    async def test_services_question_costs_one_ai_call(self):
        # The owner's live test message: the "Hello, " prefix means
        # the browse-services gate (which needs a bare "what ...")
        # does not fire, so this reaches the fast path and costs
        # exactly one AI call — the answer — instead of two.
        answer = "Paxyo offers followers, likes and views."
        msg, ai_mock = await self._send_counting(
            "Hello, what services do you offer?", [answer]
        )
        self.assertEqual(ai_mock.call_count, 1)
        self.assertEqual(msg.text_sent, [answer])

    async def test_bare_services_question_goes_to_browse(self):
        # Pre-existing behaviour, pinned here so the fast path is
        # never "fixed" into breaking it: a bare "What services do
        # you offer?" matches the browse-services gate before the
        # classifier, so it costs zero AI calls and asks which
        # platform instead of listing services.
        msg, ai_mock = await self._send_counting(
            "What services do you offer?", []
        )
        ai_mock.assert_not_called()
        self.assertEqual(
            msg.text_sent,
            ["Which platform? (Instagram, TikTok, Telegram, YouTube...)"],
        )

    async def test_order_message_still_classifies(self):
        payload = json.dumps({
            **FULL_INTENT,
            "intent": "order",
            "platform": "instagram",
            "service_hint": "instagram followers",
            "link": "https://instagram.com/p/x",
            "quantity": 1000,
        })
        msg, ai_mock = await self._send_counting(
            "I want 1000 Instagram followers https://instagram.com/p/x",
            [payload],
        )
        # The classify call ran (and nothing else called the AI):
        # the order flow itself is deterministic.
        self.assertEqual(ai_mock.call_count, 1)
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("Instagram Followers", msg.text_sent[0])
        self.assertIsNotNone(msg.markups[0])  # the Confirm card

    async def test_deposit_message_still_classifies(self):
        payload = json.dumps({"intent": "deposit", "amount": 10})
        msg, ai_mock = await self._send_counting(
            "I want to deposit 10 ETB", [payload]
        )
        self.assertEqual(ai_mock.call_count, 1)
        self.assertEqual(len(msg.text_sent), 1)

    async def test_ambiguous_message_falls_back_to_two_calls(self):
        payload = json.dumps({"intent": "off_topic"})
        msg, ai_mock = await self._send_counting(
            "What is the weather like?", [payload, "It is sunny today."]
        )
        self.assertEqual(ai_mock.call_count, 2)
        self.assertIn("It is sunny today.", msg.text_sent[0])


class TestTurnTimingLogs(unittest.IsolatedAsyncioTestCase):
    """Handler-stage timing logs (owner, 17 Nov 2026): a live reply
    took 29s while both AI calls took under 1s each, so each stage
    of a text turn logs its own timing — update age, session
    restore, services load, intent decision, answer, reply sent —
    plus the services() fetch itself. Timings and intent type only:
    the user's message text never appears in any of these lines.
    """

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot._SESSION_RESTORED.clear()
        bot.CHAT_HISTORY.clear()

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot._SESSION_RESTORED.clear()
        bot.CHAT_HISTORY.clear()

    async def _send_logged(self, text, ai_side_effect, date=None):
        msg = FakeMessage()
        if date is not None:
            msg.date = date
        update = FakeUpdate(msg)
        ai_mock = mock.AsyncMock(side_effect=list(ai_side_effect))
        with mock.patch("bot.ai_generate", ai_mock), \
             mock.patch("bot.paxyo", FakePaxyo()), \
             mock.patch("bot.speak_reply"), \
             self.assertLogs("paxorder_bot", level="INFO") as logs:
            await bot.handle_order_text(update, None, text)
            # Let the background restore (kicked off by the turn)
            # finish while paxyo is still patched, so no restore
            # task outlives the log capture.
            for _ in range(3):
                await asyncio.sleep(0)
        self.assertEqual(msg.voice_sent, [])
        return msg, ai_mock, "\n".join(logs.output)

    async def test_simple_chat_logs_every_stage(self):
        # The owner's live test message, fast path, one AI call.
        answer = "Paxyo offers followers, likes and views."
        msg, ai_mock, joined = await self._send_logged(
            "Hello, what services do you offer?",
            [answer],
            date=datetime.now(timezone.utc),
        )
        self.assertEqual(ai_mock.call_count, 1)
        self.assertEqual(msg.text_sent, [answer])
        self.assertRegex(joined, r"turn received age \d+\.\d\ds")
        self.assertRegex(joined, r"turn session \d+\.\d\ds")
        self.assertRegex(
            joined, r"turn intent paxyo_info fast \d+\.\d\ds"
        )
        self.assertRegex(joined, r"turn answer \d+\.\d\ds")
        self.assertRegex(joined, r"turn sent \d+\.\d\ds")
        # The fast path never loads the catalogue.
        self.assertNotIn("turn services", joined)

    async def test_greeting_logs_sent_without_answer(self):
        msg, ai_mock, joined = await self._send_logged(
            "Hello", [], date=datetime.now(timezone.utc)
        )
        ai_mock.assert_not_called()
        self.assertIn("Tell me the service you want", msg.text_sent[0])
        self.assertRegex(joined, r"turn received age \d+\.\d\ds")
        self.assertRegex(
            joined, r"turn intent greeting fast \d+\.\d\ds"
        )
        self.assertRegex(joined, r"turn sent \d+\.\d\ds")
        self.assertNotIn("turn answer", joined)

    async def test_turn_logs_never_carry_the_message_text(self):
        answer = "Paxyo offers followers, likes and views."
        _, _, joined = await self._send_logged(
            "Hello, what services do you offer?",
            [answer],
            date=datetime.now(timezone.utc),
        )
        self.assertNotIn("what services do you offer", joined)
        self.assertNotIn("Hello, what services", joined)
        self.assertNotIn("http", joined)

    async def test_classifier_path_logs_services_and_intent(self):
        payload = json.dumps({
            **FULL_INTENT,
            "intent": "order",
            "platform": "instagram",
            "service_hint": "instagram followers",
            "link": "https://instagram.com/p/x",
            "quantity": 1000,
        })
        msg, ai_mock, joined = await self._send_logged(
            "I want 1000 Instagram followers https://instagram.com/p/x",
            [payload],
            date=datetime.now(timezone.utc),
        )
        self.assertEqual(ai_mock.call_count, 1)
        self.assertRegex(joined, r"turn services \d+\.\d\ds")
        self.assertRegex(
            joined, r"turn intent order classifier \d+\.\d\ds"
        )

    async def test_services_fetch_logs_duration_once(self):
        client = bot.PaxyoClient()
        try:
            calls = []

            async def _fake_send(request):
                calls.append(request)
                return {"services": [
                    {"id": 1, "price": 100},
                    {"id": 2, "price": 200},
                ]}

            with mock.patch.object(client, "_send", _fake_send), \
                 self.assertLogs("paxorder_bot", level="INFO") as logs:
                first = await client.services()
            joined = "\n".join(logs.output)
            self.assertRegex(joined, r"api services fetch \d+\.\d\ds")
            # Two fetches per refresh since 19 Nov 2026 (price
            # overrides): the catalogue plus the overrides list.
            # The duration log line still appears exactly once.
            self.assertEqual(len(calls), 2)
            self.assertTrue(
                any(s.get("service") == 1 for s in first)
            )
            # Second call is served from the 10-minute cache: no
            # second fetch — and no second log line. assertLogs
            # would fail on zero records, so capture with a plain
            # handler instead.
            import logging
            records = []
            _handler = logging.Handler()
            _handler.emit = lambda record: records.append(
                record.getMessage()
            )
            _logger = logging.getLogger("paxorder_bot")
            _logger.addHandler(_handler)
            try:
                second = await client.services()
            finally:
                _logger.removeHandler(_handler)
            self.assertEqual(len(calls), 2)
            self.assertFalse(
                any("api services fetch" in m for m in records)
            )
            self.assertEqual(first, second)
        finally:
            await client._client.aclose()


class FlakyClient:
    """Fake client returning a queue of responses/errors per post."""

    def __init__(self, results):
        self._results = list(results)
        self.posts = []

    async def __aenter__(self):
        return self

    async def __aexit__(self, *exc):
        return False

    async def post(self, url, headers=None, json=None, params=None):
        self.posts.append(
            {"url": url, "headers": headers, "json": json, "params": params}
        )
        result = self._results.pop(0)
        if isinstance(result, Exception):
            raise result
        return result


class TestChosenService(unittest.IsolatedAsyncioTestCase):
    """A service the user names is used for that order instead of the
    fastest one — by ID, by description, or "same service as last
    time". Blacklisted services are never used."""

    # The live case (20 Nov 2026): the user asked for 1000 YouTube
    # subscribers with service 5413 (3.78 ETB) and the bot offered
    # its own #2427 at 92.40 ETB instead. 2427 is faster, so it is
    # the default pick; 5413 must win when named.
    YOUTUBE_SERVICES = [
        {
            "service": 2427, "name": "Youtube Subscribers | Fast",
            "category": "Youtube Subscribers", "type": "Default",
            "rate_etb_per_1000": 92.40, "min": 10, "max": 100000,
            "average_time": "1 minute", "active": True,
            "provider_service_id": 2427,
        },
        {
            "service": 5413,
            "name": "Youtube Subscribers | LQ Accounts | High Drop",
            "category": "Youtube Subscribers", "type": "Default",
            "rate_etb_per_1000": 3.78, "min": 1, "max": 100000,
            "average_time": "1 hour", "active": True,
            "provider_service_id": 5413,
        },
    ]

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot.FASTEST_FALLBACK.clear()

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
        bot.PARTIAL.clear()
        bot.PENDING_RECURRING.clear()
        bot.RECURRING_DRAFT.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot.FASTEST_FALLBACK.clear()

    async def _turns(self, turns, paxyo=None):
        """Send several messages in sequence, sharing one FakeMessage
        so text_sent accumulates; returns (msg, fake_paxyo)."""
        msg = FakeMessage()
        update = FakeUpdate(msg)
        fake_paxyo = paxyo or FakePaxyo()
        intents = [intent for _, intent in turns]
        with mock.patch(
            "bot.extract_intent", new=mock.AsyncMock(side_effect=intents)
        ), mock.patch("bot.paxyo", fake_paxyo), mock.patch("bot.speak_reply"):
            for text, _ in turns:
                await bot.handle_order_text(update, None, text)
        return msg, fake_paxyo

    def test_extract_service_id_forms(self):
        self.assertEqual(bot.extract_service_id("use service 6139"), 6139)
        self.assertEqual(bot.extract_service_id("service #5535"), 5535)
        self.assertEqual(bot.extract_service_id("#6139"), 6139)
        self.assertEqual(bot.extract_service_id("order with 7246"), 7246)
        self.assertEqual(bot.extract_service_id("6139"), 6139)
        self.assertEqual(bot.extract_service_id("105"), 105)

    def test_extract_service_id_ignores_quantities(self):
        # Quantities are multiples of 10, so a bare "2000" is a
        # quantity, never a service ID.
        self.assertIsNone(bot.extract_service_id("2000"))
        self.assertIsNone(bot.extract_service_id("use 2000"))
        self.assertIsNone(bot.extract_service_id("order 1000 instagram followers"))
        self.assertIsNone(bot.extract_service_id("15"))

    def test_extract_service_id_id_word_forms(self):
        # 20 Nov 2026: "service id 5413" and "id 5413" name the
        # service too — the user asked for the cheap 5413 service
        # by its number and the bot must hear it.
        self.assertEqual(bot.extract_service_id("service id 6139"), 6139)
        self.assertEqual(bot.extract_service_id("id 6139"), 6139)
        self.assertEqual(bot.extract_service_id("use service id 6139"), 6139)
        self.assertEqual(
            bot.extract_service_id(
                "I want 1000 YouTube subscribers service id 5413 "
                "https://www.youtube.com/@johannesabate3089"
            ),
            5413,
        )
        self.assertEqual(bot.extract_service_id("with service 5413"), 5413)
        # A quantity after "id" is still a quantity, never an ID.
        self.assertIsNone(bot.extract_service_id("id 2000"))

    def test_find_service_by_panel_id_field(self):
        # A panel service ID resolves even when the catalogue row
        # carries the number under provider_service_id / id rather
        # than "service".
        services = [
            {"service": 9001, "provider_service_id": 5413, "id": 77,
             "name": "Youtube Subscribers | LQ", "active": True},
        ]
        found = bot.find_service_by_id(services, 5413)
        self.assertIsNotNone(found)
        self.assertEqual(found["provider_service_id"], 5413)
        service, error = bot.resolve_named_service(services, 5413)
        self.assertIsNone(error)
        self.assertEqual(service["provider_service_id"], 5413)

    def test_mentions_same_service(self):
        self.assertTrue(bot.mentions_same_service("use that service again"))
        self.assertTrue(bot.mentions_same_service("same service as last time"))
        self.assertTrue(bot.mentions_same_service("the last service please"))
        self.assertFalse(bot.mentions_same_service("order 1000 followers"))
        self.assertFalse(bot.mentions_same_service("order on that link again"))

    def test_resolve_named_service(self):
        service, error = bot.resolve_named_service(SAMPLE_SERVICES, 1001)
        self.assertIsNone(error)
        self.assertEqual(service["service"], 1001)
        self.assertEqual(
            bot.resolve_named_service(SAMPLE_SERVICES, 5379),
            (None, "blacklisted"),
        )
        self.assertEqual(
            bot.resolve_named_service(SAMPLE_SERVICES, 5834),
            (None, "blacklisted"),
        )
        self.assertEqual(
            bot.resolve_named_service(SAMPLE_SERVICES, 999999999),
            (None, "not_found"),
        )
        self.assertEqual(
            bot.resolve_named_service(SAMPLE_SERVICES, 1004),
            (None, "disabled"),
        )

    def test_pick_services_cheapest_description(self):
        # "cheapest instagram followers" ranks by price, not time:
        # 1002 (21 ETB) beats 1001 (42) and 1003 (30).
        picks = bot.pick_services(
            SAMPLE_SERVICES, platform="instagram",
            service_hint="cheapest instagram followers",
        )
        self.assertEqual(picks[0]["service"], 1002)

    def test_pick_services_word_based_hint(self):
        picks = bot.pick_services(
            SAMPLE_SERVICES, platform="instagram",
            service_hint="instagram followers",
        )
        self.assertEqual(
            [s["service"] for s in picks], [1001, 1002, 1003]
        )

    async def test_named_service_id_wins_over_fastest(self):
        # 1002 is slower than 1001 — naming it must still use it.
        msg, _ = await self._turns([
            ("order 1000 Instagram followers with service 1002", intent_of(
                "order", platform="instagram", service_hint="followers",
                link="https://instagram.com/p/x", quantity=1000,
                service_id=1002)),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("Instagram Followers | Slow (#1002)", msg.text_sent[0])
        self.assertIsNotNone(msg.markups[0])  # the Confirm card
        pending = next(iter(bot.PENDING.values()))
        self.assertEqual(pending["service"]["service"], 1002)

    async def test_service_id_5413_beats_default(self):
        # The live case (20 Nov 2026): the user asked for 1000
        # YouTube subscribers with service 5413 and the bot
        # offered its own #2427 at 92.40 ETB instead. Naming the
        # ID must use that service at its price. Gemini misses
        # the ID here on purpose: the local regex must catch it.
        msg, _ = await self._turns([
            ("I want 1000 YouTube subscribers service id 5413 "
             "https://www.youtube.com/@johannesabate3089",
             intent_of(
                "order", platform="youtube",
                service_hint="youtube subscribers",
                link="https://www.youtube.com/@johannesabate3089",
                quantity=1000)),
        ], paxyo=FakePaxyo(services=self.YOUTUBE_SERVICES))
        self.assertEqual(len(msg.text_sent), 1)
        card = msg.text_sent[0]
        self.assertIn("(#5413)", card)
        self.assertIn("3.78 ETB / 1000", card)
        self.assertIn("3.78 ETB (estimated)", card)
        self.assertNotIn("92.40", card)
