        self.assertIn('Please confirm, 3 orders:', msg.text_sent[0])
        self.assertIn("@user1", msg.text_sent[0])
        self.assertIn("https://instagram.com/p/a", msg.text_sent[0])
        self.assertIn("Total: 136.50 ETB", msg.text_sent[0])
