class TestGrokProvider(unittest.IsolatedAsyncioTestCase):
    """Grok (xAI) is the third AI since 17 Nov 2026 (owner: Groq
    first, DeepSeek second, Grok third). xAI's API is
    OpenAI-compatible, so the provider mirrors DeepSeek exactly.
    Order: Groq -> DeepSeek -> Grok -> Zen -> Qwen -> Mistral ->
    OpenAI -> Gemini -> Kilo -> OpenRouter -> GLM. Grok is
    expensive vs DeepSeek and only runs when GROK_API_KEY is set;
    without the key the order is unchanged (Groq first, DeepSeek
    second).
    Grok has no voice transcription — ai_transcribe is Gemini
    (Groq only as emergency fallback). NOTE: GROQ_API_KEY is a different company
    (Groq) and cannot be used for Grok."""

    def _status_error(self, status):
        req = bot.httpx.Request(
            "POST", "https://api.x.ai/v1/chat/completions"
        )
        resp = bot.httpx.Response(status, request=req)
        return bot.httpx.HTTPStatusError(f"{status}", request=req, response=resp)

    def _ok_response(self, text="hello"):
        return FakeCloudTTSResponse({
            "choices": [{"message": {"content": text}}]
        })

    def test_grok_default_model_is_grok_4(self):
        self.assertEqual(bot.GROK_MODEL, "grok-4")

    async def test_grok_generate_returns_reply_text(self):
        client = GroqFlakyClient([self._ok_response()])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROK_API_KEY", "xai-test"):
            self.assertEqual(await bot.grok_generate("hi"), "hello")
        post = client.posts[0]
        self.assertTrue(post["url"].endswith("/chat/completions"))
        self.assertTrue(post["url"].startswith("https://api.x.ai/v1"))
        self.assertEqual(
            post["headers"]["Authorization"], "Bearer xai-test"
        )
        self.assertEqual(post["json"]["model"], "grok-4")
        self.assertEqual(
            post["json"]["messages"], [{"role": "user", "content": "hi"}]
        )

    async def test_grok_generate_with_system_message(self):
        client = GroqFlakyClient([self._ok_response()])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROK_API_KEY", "xai-test"):
            await bot.grok_generate("hi", system="be helpful")
        self.assertEqual(
            client.posts[0]["json"]["messages"],
            [
                {"role": "system", "content": "be helpful"},
                {"role": "user", "content": "hi"},
            ],
        )

    async def test_grok_generate_fails_fast_on_429(self):
        # Fast failover (17 Nov 2026): a 429 raises at once —
        # no retry, no sleep — so ai_generate falls through.
        client = GroqFlakyClient(
            [self._status_error(429)]
        )
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROK_API_KEY", "xai-test"), \
             mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()) as sleep_mock:
            with self.assertRaises(bot.httpx.HTTPStatusError):
                await bot.grok_generate("hi")
        self.assertEqual(len(client.posts), 1)
        sleep_mock.assert_not_awaited()

    async def test_ai_generate_grok_third_after_groq_and_deepseek_fail(self):
        # Groq and DeepSeek both fail: Grok answers third.
        with mock.patch.object(bot, "GROQ_API_KEY", "gsk-test"), \
             mock.patch.object(bot, "GROK_API_KEY", "xai-test"), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", "sk-deepseek-test"), \
             mock.patch(
                 "bot.groq_generate",
                 new=mock.AsyncMock(
                     side_effect=RuntimeError("groq down")
                 ),
             ) as groq, \
             mock.patch(
                 "bot.grok_generate",
                 new=mock.AsyncMock(return_value="k"),
             ) as grok, \
             mock.patch(
                 "bot.deepseek_generate",
                 new=mock.AsyncMock(
                     side_effect=RuntimeError("deepseek down")
                 ),
             ) as deepseek, \
             mock.patch(
                 "bot.gemini_generate", new=mock.AsyncMock()
             ) as gem:
            self.assertEqual(await bot.ai_generate("hello"), "k")
        groq.assert_awaited_once()
        deepseek.assert_awaited_once()
        grok.assert_awaited_once()
        gem.assert_not_called()

    async def test_ai_generate_falls_back_to_zen_when_grok_raises(self):
        # Groq and DeepSeek unset, Grok 429s (daily limit) and fails
        # fast: Zen takes over.
        with mock.patch.object(bot, "GROQ_API_KEY", ""), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", ""), \
             mock.patch.object(bot, "GROK_API_KEY", "xai-test"), \
             mock.patch.object(bot, "ZEN_API_KEY", "sk-zen-test"), \
             mock.patch(
                 "bot.groq_generate", new=mock.AsyncMock()
             ) as groq, \
             mock.patch(
                 "bot.grok_generate",
                 new=mock.AsyncMock(
                     side_effect=RuntimeError("grok down")
                 ),
             ) as grok, \
             mock.patch(
                 "bot.deepseek_generate", new=mock.AsyncMock()
             ) as deepseek, \
             mock.patch(
                 "bot.zen_generate",
                 new=mock.AsyncMock(return_value="z"),
             ) as zen, \
             mock.patch(
                 "bot.gemini_generate", new=mock.AsyncMock()
             ) as gem:
            self.assertEqual(await bot.ai_generate("hello"), "z")
        groq.assert_not_called()
        deepseek.assert_not_called()
        grok.assert_awaited_once()
        zen.assert_awaited_once()
        gem.assert_not_called()

    async def test_ai_generate_deepseek_first_without_groq_and_grok_keys(self):
        # No GROQ_API_KEY and no GROK_API_KEY: the order is
        # unchanged, DeepSeek first.
        with mock.patch.object(bot, "GROQ_API_KEY", ""), \
             mock.patch.object(bot, "GROK_API_KEY", ""), \
             mock.patch.object(bot, "DEEPSEEK_API_KEY", "sk-deepseek-test"), \
             mock.patch(
                 "bot.groq_generate", new=mock.AsyncMock()
             ) as groq, \
             mock.patch(
                 "bot.grok_generate", new=mock.AsyncMock()
             ) as grok, \
             mock.patch(
                 "bot.deepseek_generate",
                 new=mock.AsyncMock(return_value="d"),
             ) as deepseek, \
             mock.patch(
                 "bot.gemini_generate", new=mock.AsyncMock()
             ) as gem:
            self.assertEqual(await bot.ai_generate("hello"), "d")
        groq.assert_not_called()
        grok.assert_not_called()
        deepseek.assert_awaited_once()
        gem.assert_not_called()

    async def test_ai_generate_grok_failure_logs_no_bearer(self):
        err = self._status_error(404)
        client = GroqFlakyClient([err, err, err])
        with mock.patch("bot.httpx.AsyncClient", return_value=client), \
             mock.patch.object(bot, "GROK_API_KEY", "xai-test"), \
             mock.patch.object(
                 bot, "gemini_generate", new=mock.AsyncMock(return_value="hello")
             ), mock.patch.object(bot.asyncio, "sleep", new=mock.AsyncMock()), \
             self.assertLogs("paxorder_bot", level="WARNING") as logs:
            result = await bot.ai_generate("hi")
        self.assertEqual(result, "hello")
        joined = "\n".join(logs.output)
        self.assertIn(
            "Grok generate failed, trying next provider (HTTP 404)",
            joined,
        )
        self.assertNotIn("Bearer ", joined)
        self.assertNotIn("xai-test", joined)
        self.assertNotIn("key=", joined)


