class TestLanguageRound(_LanguageRoundBase):
    """Owner rule, 14 Nov 2026: the bot replies in the language of
    the user's CURRENT message — English in, English out; Amharic
    in, Amharic out — and Oromo (Afaan Oromo) and Tigrinya get the
    same treatment as Amharic. The live bug was a stuck bridge
    flag: an Amharic turn translated every later English reply
    back to Amharic."""

    def test_detect_language_samples(self):
        cases = (
            ("ሰላም, የቲክቶክ ተከታዮች መግዛት እፈልጋለሁ", "am"),
            ("ሰላም! ኣነ Paxyo Order bot እየ።", "ti"),
            ("ኣነ 1000 TikTok followers እደሊ", "ti"),
            ("Akkam, tajaajila TikTok barbaada", "om"),
            ("galatoomi, meeqa views?", "om"),
            ("I want 1000 views", "en"),
            ("I want 1000 views", "en"),
        )
        for text, expected in cases:
            with self.subTest(text=text):
                self.assertEqual(bot.detect_language(text), expected)
        # The account language never overrides the words typed:
        # English text stays English even on an Amharic account.
        self.assertEqual(bot.detect_language("I want 1000 views", "am"), "en")
        self.assertEqual(bot.lang_of("I want 1000 views", "am"), "en")
        # ... and is only the fallback when the message itself
        # carries no language signal (a bare number, an emoji).
        self.assertEqual(bot.detect_language("1000", "am"), "am")
        self.assertEqual(bot.detect_language("1000", "en"), "en")
        self.assertEqual(bot.detect_language("👍", ""), "en")

    def test_t_falls_back_to_english_for_missing_language(self):
        # Keys with no Oromo/Tigrinya version fall back to English
        # (the bridge translates prose replies at send time).
        self.assertEqual(
            bot.t("ask_link", "om"), bot.t("ask_link", "en")
        )
        self.assertEqual(
            bot.t("ask_link", "ti"), bot.t("ask_link", "en")
        )
        # Keys with a version use it.
        self.assertIn("argachuu", bot.t("contact_owner", "om"))
        self.assertIn("t.me/paxyo", bot.t("contact_owner", "om"))
        self.assertIn("ተዓጺዩ", bot.t("paused_services", "ti"))
        self.assertIn(
            "hin kufan",
            bot.t("never_drop", "om", service="Telegram reactions"),
        )
        self.assertIn(
            "ኣይወድቁን",
            bot.t("never_drop", "ti", service="Telegram reactions"),
        )

    async def test_reply_follows_current_message_after_switch(self):
        # The live repro: an Amharic turn, then the English
        # "I'm tired today" — the second reply must be English,
        # not translated back to Amharic.
        amharic_q = "አገልግሎቶችዎን ከየት ታገኛላችሁ?"
        with mock.patch(
            "bot.translate_to_english",
            new=mock.AsyncMock(
                return_value="where do you get your services"
            ),
        ), mock.patch(
            "bot.translate_to_amharic",
            new=mock.AsyncMock(return_value="AMHARIC-REPLY"),
        ) as to_am, mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(
                side_effect=AssertionError("classifier must not run")
            ),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.speak_reply"
        ):
            msg = FakeMessage()
            await bot.handle_order_text(FakeUpdate(msg), None, amharic_q)
            self.assertEqual(msg.text_sent, ["AMHARIC-REPLY"])
            to_am.assert_awaited_once()
        # Same task, next turn, English: the bridge must NOT fire.
        with mock.patch(
            "bot.translate_to_english",
            new=mock.AsyncMock(
                side_effect=AssertionError("must not translate English")
            ),
        ), mock.patch(
            "bot.translate_to_amharic",
            new=mock.AsyncMock(
                side_effect=AssertionError("must not translate back")
            ),
        ) as to_am2, mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(
                return_value="Hope you feel better soon."
            ),
        ), mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(
                side_effect=AssertionError("classifier must not run")
            ),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.speak_reply"
        ):
            msg2 = FakeMessage()
            await bot.handle_order_text(
                FakeUpdate(msg2), None, "I'm tired today"
            )
        self.assertIn("Hope you feel better soon.", msg2.text_sent[0])
        self.assertNotIn("AMHARIC", msg2.text_sent[0])
        to_am2.assert_not_awaited()
        self.assertIsNone(bot._BRIDGE_LANG.get())

    async def test_oromo_order_is_bridged_to_english(self):
        oromo = (
            "Akkam, 200 TikTok views barbaada: "
            "https://vt.tiktok.com/ZSpQWTSmH/"
        )
        english = (
            "please order 200 TikTok views for this video: "
            "https://vt.tiktok.com/ZSpQWTSmH/"
        )
        intent = intent_of(
            "order", platform="tiktok", service_hint="views",
            link="https://vt.tiktok.com/ZSpQWTSmH/", quantity=200,
        )
        with mock.patch(
            "bot.translate_to_english",
            new=mock.AsyncMock(return_value=english),
        ) as to_en, mock.patch(
            "bot.translate_to_amharic",
            new=mock.AsyncMock(
                side_effect=AssertionError(
                    "Confirm card must not be translated"
                )
            ),
        ), mock.patch(
            "bot.translate_to_language",
            new=mock.AsyncMock(
                side_effect=AssertionError(
                    "Confirm card must not be translated"
                )
            ),
        ), mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent),
        ) as extract, mock.patch(
            "bot.paxyo", TikTokPaxyo()
        ), mock.patch("bot.speak_reply"):
            msg = FakeMessage()
            await bot.handle_order_text(FakeUpdate(msg), None, oromo)
        self.assertEqual(
            to_en.await_args.args[0], bot.normalize_text(oromo)
        )
        self.assertEqual(to_en.await_args.kwargs.get("source_lang"), "om")
        extract.assert_awaited_once()
        self.assertEqual(extract.await_args.args[0], english)
        self.assertEqual(len(bot.PENDING), 1)
        self.assertIn("Please confirm", msg.text_sent[0])
        self.assertIsNotNone(msg.markups[0])

    async def test_tigrinya_reply_is_translated_back(self):
        tigrinya = "ኣነ 1000 TikTok followers እደሊ"
        english = "I want 1000 TikTok followers"
        intent = intent_of(
            "order", platform="tiktok", service_hint="followers",
            quantity=1000,
        )
        with mock.patch(
            "bot.translate_to_english",
            new=mock.AsyncMock(return_value=english),
        ) as to_en, mock.patch(
            "bot.translate_to_language",
            new=mock.AsyncMock(return_value="ሊንክ ይላኩ"),
        ) as to_ti, mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent),
        ), mock.patch(
            "bot.paxyo", TikTokPaxyo()
        ), mock.patch("bot.speak_reply"):
            msg = FakeMessage()
            await bot.handle_order_text(FakeUpdate(msg), None, tigrinya)
        self.assertEqual(
            to_en.await_args.args[0], bot.normalize_text(tigrinya)
        )
        self.assertEqual(to_en.await_args.kwargs.get("source_lang"), "ti")
        self.assertEqual(to_ti.await_args.args, ("Please send your TikTok profile link.", "ti"))
        self.assertEqual(msg.text_sent, ["ሊንክ ይላኩ"])

    async def test_translate_prompts_name_the_language(self):
        with mock.patch(
            "bot.gemini_generate",
            new=mock.AsyncMock(return_value="hello"),
        ) as gen:
            await bot.translate_to_english("ሰላም", source_lang="ti")
        self.assertIn("Tigrinya", gen.await_args.args[0])
        with mock.patch(
            "bot.gemini_generate",
            new=mock.AsyncMock(return_value="akkam"),
        ) as gen:
            await bot.translate_to_language("Hello", "om")
        self.assertIn("Oromo", gen.await_args.args[0])
        self.assertIn("service names", gen.await_args.args[0])


class TestPriceFastPath(_LanguageRoundBase):
    """Live bug, 14 Nov 2026: the 👍 price arrived 68 seconds late
    as a separate message, because the price answer waited on the
    AI classifier and the bridge. Price questions are now answered
    from local detection only, before the classifier runs — the
    greeting branch (and any other post-classification branch)
    can never swallow one, and the classifier is never called for
    it at all."""

    async def _send(self, text, paxyo=None, intent=_UNSET):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        patches = [
            mock.patch("bot.paxyo", paxyo or FakePaxyo()),
            mock.patch("bot.speak_reply"),
        ]
        if intent is _UNSET:
            patches.append(mock.patch(
                "bot.extract_intent",
                new=mock.AsyncMock(
                    side_effect=AssertionError("classifier must not run")
                ),
            ))
        else:
            patches.append(mock.patch(
                "bot.extract_intent",
                new=mock.AsyncMock(return_value=intent),
            ))
        from contextlib import ExitStack
        with ExitStack() as stack:
            for patch in patches:
                stack.enter_context(patch)
            await bot.handle_order_text(update, None, text)
        return msg

    async def test_price_question_never_calls_classifier(self):
        # The live repro: the greeting reply the retest saw was a
        # late answer to an earlier message, but the price itself
        # waited on the classifier. Now one reply goes out, with
        # the price, and the classifier never runs.
        msg = await self._send(
            "I want 👍 reaction for my telegram channel post how much 1k",
            paxyo=RealReactionsPaxyo(),
        )
        self.assertEqual(len(msg.text_sent), 1)
        reply = msg.text_sent[0]
        self.assertIn("Thumbs up 👍", reply)
        self.assertIn("5.46 ETB for 1,000", reply)
        self.assertNotIn("Hello! I am the Paxyo Order bot", reply)

    async def test_greeting_intent_cannot_swallow_price_question(self):
        # Even on the fallback path (the fast-path lookup fails
        # once, so the classifier runs), a "greeting" verdict must
        # not swallow the price — the post-classification price
        # branch runs before the greeting branch.
        msg = await self._send(
            "I want 👍 reaction for my telegram channel post how much 1k",
            paxyo=FlakyReactionsPaxyo(),
            intent=intent_of(
                "greeting", platform="telegram",
                service_hint="telegram reactions", quantity=1000,
            ),
        )
        self.assertEqual(len(msg.text_sent), 1)
        reply = msg.text_sent[0]
        self.assertIn("Thumbs up 👍", reply)
        self.assertIn("5.46 ETB for 1,000", reply)
        self.assertNotIn("Hello! I am the Paxyo Order bot", reply)

    async def test_fast_path_uses_conversation_platform(self):
        # A bare "how much are the views?" while a TikTok views
        # draft is being built is about TikTok views — not the
        # faster, cheaper Instagram views in the same catalogue.
        # Mid-order understanding (16 Nov 2026): the price is
        # answered AND the open draft is parked first, so the
        # parked line comes before the price.
        bot.PARTIAL[1] = {"platform": "tiktok", "service_hint": "views"}
        msg = await self._send(
            "how much are the views?",
            paxyo=TwoPlatformViewsPaxyo(),
        )
        self.assertEqual(len(msg.text_sent), 2)
        self.assertIn(
            "unfinished order is saved", msg.text_sent[0].lower())
        reply = msg.text_sent[1]
        self.assertIn("TikTok", reply)
        self.assertIn("18.90", reply)
        self.assertNotIn("Instagram", reply)
        self.assertEqual(bot.PARTIAL, {})
        self.assertEqual(
            bot.PARKED_DRAFT[1].get("platform"), "tiktok")

    async def test_link_plus_price_word_answers_cheapest_for_link(self):
        # Ideas batch 1 #2 (16 Nov 2026): a video link + "how much
        # is the price" answers the cheapest VIEWS price for that
        # link — not the fastest TikTok service of any metric (the
        # Video Save service at 2.10, which the old code quoted).
        # No draft is started and "How many?" is never asked.
        msg = await self._send(
            "https://www.tiktok.com/@user/video/1234567890 "
            "how much is the price",
            paxyo=TikTokPaxyo(),
        )
        self.assertEqual(len(msg.text_sent), 1)
        reply = msg.text_sent[0]
        self.assertIn("TikTok Video Views", reply)
        self.assertIn("1.51 ETB per 1000", reply)
        self.assertNotIn("2.10", reply)
        self.assertNotIn("How many?", reply)
        self.assertEqual(bot.PARTIAL, {})
        self.assertEqual(bot.PENDING, {})

    async def test_profile_link_plus_price_word_answers_followers(self):
        # A profile link + a price word is about followers — the
        # cheapest followers price, not the fastest (42.00).
        msg = await self._send(
            "https://instagram.com/someuser how much is the price",
        )
        self.assertEqual(len(msg.text_sent), 1)
        reply = msg.text_sent[0]
        self.assertIn("Instagram Followers", reply)
        self.assertIn("21.00 ETB per 1000", reply)
        self.assertNotIn("42.00", reply)
        self.assertEqual(bot.PARTIAL, {})

    async def test_link_plus_price_word_named_metric_wins(self):
        # A metric the message itself names ("likes") wins over
        # the metric the link shape would imply (views).
        msg = await self._send(
            "https://www.tiktok.com/@user/video/1234567890 "
            "how much are the likes",
            paxyo=TikTokPaxyo(),
        )
        reply = msg.text_sent[0]
        self.assertIn("TikTok Likes", reply)
        self.assertIn("10.00 ETB per 1000", reply)
        self.assertNotIn("Views", reply)

    async def test_bare_link_keeps_order_flow(self):
        # A bare link with NO price word is still an order, not a
        # price check: the bot asks "How many?" and quotes no price.
        msg = await self._send(
            "https://www.tiktok.com/@user/video/1234567890",
            paxyo=TikTokPaxyo(),
            intent=intent_of(
                "order", platform="tiktok", service_hint="views",
                link="https://www.tiktok.com/@user/video/1234567890",
            ),
        )
        reply = msg.text_sent[-1]
        self.assertIn("How many?", reply)
        self.assertNotIn("ETB per 1000", reply)

    async def test_tiktok_likes_fastest_pick_matches_live_price(self):
        # The live 14 Nov 2026 figure (1,185.05 ETB for 5,000) is
        # the FASTEST TikTok Likes service (237.01/1000, "Instant
        # Start" — live #5812/#2374), not the cheapest (6.30) and
        # never the blacklisted #5379 (5.88). Fastest-first, not
        # cheapest-first, is the documented pick rule.
        msg = await self._send(
            "how much is 5000 tiktok likes?",
            paxyo=FastestLikesPaxyo(),
        )
        reply = msg.text_sent[0]
        self.assertIn("TikTok Likes", reply)
        self.assertIn("1,185.05", reply)
        self.assertIn("5,000", reply)
        self.assertNotIn("31.50", reply)


class StaleDraftPricePaxyo(FakePaxyo):
    """TikTok views + Instagram views + the Telegram Reactions
    Positive mix from William's 16 Nov 2026 screenshot (37.80
    ETB/1000, min 50). Instagram views are faster AND cheaper than
    TikTok views, so only the CURRENT draft can keep a bare price
    question on TikTok — a stale reactions draft would answer
    37.80."""

    STALE_SERVICES = [
        {
            "service": 2001, "name": "TikTok Video Views | Fast",
            "category": "TikTok Video Views", "type": "Default",
            "rate_etb_per_1000": 18.90, "min": 10, "max": 100000,
            "average_time": "5 minutes", "active": True,
        },
        {
            "service": 3001, "name": "Instagram Views | Fast",
            "category": "Instagram Views", "type": "Default",
            "rate_etb_per_1000": 9.00, "min": 10, "max": 100000,
            "average_time": "1 minute", "active": True,
        },
        {
            "service": 6534,
            "name": "Telegram Reactions + Free Views — Positive - 👍❤️🔥🎉😄",
            "category": "Telegram Reactions", "type": "Default",
            "rate_etb_per_1000": 37.80, "min": 50, "max": 1000000,
            "average_time": "10 minutes", "active": True,
        },
    ]

    def __init__(self):
        super().__init__()
        self.fail_next_services = False

    async def services(self):
        if self.fail_next_services:
            self.fail_next_services = False
            raise RuntimeError("catalogue hiccup")
        return list(self.STALE_SERVICES)


class TestStaleDraftPrice(_LanguageRoundBase):
    """Live bug, 16 Nov 2026 18:11 EAT (screenshot): the user said
    \"Hi\", then \"I want tiktok views\" (bot asked for the video
    link), then \"How much is the price\" — and the bot answered
    with the OLD Telegram Reactions Positive price (37.80 ETB/1000)
    from an earlier conversation instead of the TikTok views price.
    A new order must replace a stale draft, and a price question
    must be answered from the CURRENT draft — never from a stale
    or previous one. With no draft at all, the bot asks which
    service instead of guessing an old one."""

    async def _turns(self, turns, paxyo=None):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        # The simple-chat fast path (17 Nov 2026) answers a plain
        # greeting locally, so those turns never call the classifier:
        # the mocked intents line up with the turns that do.
        intents = [
            intent for text, intent in turns
            if bot.simple_chat_intent(text) is None
        ]
        with mock.patch(
            "bot.extract_intent", new=mock.AsyncMock(side_effect=intents)
        ), mock.patch("bot.paxyo", paxyo or StaleDraftPricePaxyo()), mock.patch(
            "bot.speak_reply"
        ):
            for text, _ in turns:
                await bot.handle_order_text(update, None, text)
        return msg

    def _seed_reactions_draft(self):
        # The draft left over from the earlier conversation: a
        # Telegram reactions order (link + quantity 10, which the
        # bot had already rejected for being below the min 50).
        bot.PARTIAL[1] = {
            "platform": "telegram",
            "service_hint": "telegram reactions",
            "link": "https://t.me/kefayemikiragelglot/1689743",
            "reaction_emoji": "👍",
            "quantity": 10,
        }

    async def test_price_question_answers_current_draft_not_stale_one(self):
        # The exact screenshot flow. The third turn's mocked
        # classifier intent deliberately carries the STALE
        # telegram/reactions hint forward (what the live AI did) —
        # the price must still come from the TikTok views draft
        # being built now.
        self._seed_reactions_draft()
        msg = await self._turns([
            ("Hi", intent_of("greeting")),
            ("I want tiktok views", intent_of(
                "order", platform="tiktok",
                service_hint="tiktok views",
            )),
            ("How much is the price", intent_of(
                "price", platform="telegram",
                service_hint="telegram reactions",
            )),
        ])
        # Mid-order understanding (16 Nov 2026): the "Hi"
        # parks the seeded reactions draft (parked line + greeting),
        # the order turn asks for the link, and the price turn parks
        # the TikTok draft (parked line + price) — five replies.
        self.assertEqual(len(msg.text_sent), 5)
        self.assertIn(
            "unfinished order is saved", msg.text_sent[0].lower())
        self.assertIn("video", msg.text_sent[2].lower())
        self.assertIn(
            "unfinished order is saved", msg.text_sent[3].lower())
        reply = msg.text_sent[4]
        self.assertIn("TikTok", reply)
        self.assertIn("18.90", reply)
        self.assertNotIn("37.80", reply)
        self.assertNotIn("Reactions", reply)
        self.assertEqual(bot.PARTIAL, {})
        self.assertEqual(
            bot.PARKED_DRAFT[1].get("service_hint"), "tiktok views")

    async def test_new_order_with_stale_classifier_hint_still_switches(self):
        # Even when the classifier itself carries the old
        # telegram/reactions hint forward for the NEW order
        # message, the message's own words ("I want tiktok views")
        # win: the draft switches platform, and the bot asks for
        # the TikTok video link — never the old Telegram link.
        self._seed_reactions_draft()
        msg = await self._turns([
            ("I want tiktok views", intent_of(
                "order", platform="telegram",
                service_hint="telegram reactions",
            )),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("video", msg.text_sent[0].lower())
        self.assertEqual(bot.PARTIAL[1].get("platform"), "tiktok")
        self.assertEqual(
            bot.PARTIAL[1].get("service_hint"), "tiktok views"
        )
        self.assertIsNone(bot.PARTIAL[1].get("link"))

    async def test_price_question_with_no_draft_asks_which_service(self):
        # No draft, no service just discussed: ask which service
        # instead of guessing an old one.
        msg = await self._turns([
            ("How much is the price", intent_of("price")),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("Which service?", msg.text_sent[0])
        self.assertNotIn("ETB per 1000", msg.text_sent[0])

    async def test_price_fallthrough_ignores_stale_classifier_hint(self):
        # The same price question, but the fast path fails (one
        # catalogue hiccup), so the classifier runs and returns the
        # stale telegram/reactions hint from history. The
        # post-classification price branch must STILL answer from
        # the TikTok views draft being built — never from the
        # classifier's carried-forward hint.
        self._seed_reactions_draft()
        fake_paxyo = StaleDraftPricePaxyo()
        msg = FakeMessage()
        update = FakeUpdate(msg)
        intents = [
            # The "Hi" turn is answered by the simple-chat fast
            # path (17 Nov 2026) and never calls the classifier,
            # so the mocked intents start at the order turn.
            intent_of(
                "order", platform="tiktok",
                service_hint="tiktok views",
            ),
            intent_of(
                "price", platform="telegram",
                service_hint="telegram reactions",
            ),
        ]
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(side_effect=intents),
        ), mock.patch("bot.paxyo", fake_paxyo), mock.patch(
            "bot.speak_reply"
        ):
            await bot.handle_order_text(update, None, "Hi")
            await bot.handle_order_text(
                update, None, "I want tiktok views"
            )
            fake_paxyo.fail_next_services = True
            await bot.handle_order_text(
                update, None, "How much is the price"
            )
        # Mid-order understanding (16 Nov 2026): same five
        # replies as the fast-path version — the "Hi" parks the
        # seeded draft, the price turn parks the TikTok draft.
        self.assertEqual(len(msg.text_sent), 5)
        self.assertIn(
            "unfinished order is saved", msg.text_sent[0].lower())
        self.assertIn("video", msg.text_sent[2].lower())
        self.assertIn(
            "unfinished order is saved", msg.text_sent[3].lower())
        reply = msg.text_sent[4]
        self.assertIn("TikTok", reply)
        self.assertIn("18.90", reply)
        self.assertNotIn("37.80", reply)
        self.assertNotIn("Reactions", reply)
        self.assertEqual(bot.PARTIAL, {})
        self.assertEqual(
            bot.PARKED_DRAFT[1].get("service_hint"), "tiktok views")


