class TestWrongPlatformPrice(_LanguageRoundBase):
    """Live bug, 17 Nov 2026 ~23:41 EAT (screenshot): "Twitter"
    -> "Follower" -> "How much is it" quoted Facebook Followers
    87.43 ETB/1000 instead of X/Twitter Followers 1,260.00. The
    classifier read the bare platform word as an info question,
    so the platform never reached the draft, and the price
    lookup ran with platform=None and picked the fastest
    followers service on ANY platform. Two fixes: the guard
    (a platform-less price lookup asks which service) and the
    seed (a bare platform word is remembered in the draft)."""

    async def _turns(self, turns, paxyo=None):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        # The simple-chat fast path (17 Nov 2026) answers a plain
        # greeting locally, so those turns never call the classifier:
        # the mocked intents line up with the turns that do.
        intents = [
            intent for text, intent in turns
            if bot.simple_chat_intent(text) is None
        ]
        with mock.patch(
            "bot.extract_intent", new=mock.AsyncMock(side_effect=intents)
        ), mock.patch("bot.paxyo", paxyo or TwoPlatformFollowersPaxyo()), mock.patch(
            "bot.speak_reply"
        ), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(return_value=(
                "We offer followers, likes, views, comments and more."
            )),
        ):
            for text, _ in turns:
                await bot.handle_order_text(update, None, text)
        return msg

    def test_bare_platform_word(self):
        self.assertEqual(bot._bare_platform_word("Twitter"), "x")
        self.assertEqual(bot._bare_platform_word("Twitter?"), "x")
        self.assertEqual(bot._bare_platform_word("TikTok"), "tiktok")
        self.assertEqual(bot._bare_platform_word("X"), "x")
        self.assertEqual(bot._bare_platform_word("FB"), "facebook")
        self.assertIsNone(bot._bare_platform_word("what is Twitter?"))
        self.assertIsNone(
            bot._bare_platform_word("how does Twitter work?"))
        self.assertIsNone(bot._bare_platform_word("Twitter followers"))
        self.assertIsNone(bot._bare_platform_word("max"))
        self.assertIsNone(bot._bare_platform_word(""))
        self.assertIsNone(bot._bare_platform_word("hello"))

    async def test_platformless_followers_draft_asks_which_service(self):
        # The guard: a followers draft with NO platform must never
        # be quoted the fastest followers price on any platform.
        bot.PARTIAL[1] = {"service_hint": "followers"}
        msg = await self._turns([
            ("How much is it", intent_of("price")),
        ])
        self.assertEqual(len(msg.text_sent), 2)
        self.assertIn(
            "unfinished order is saved", msg.text_sent[0].lower())
        self.assertIn("Which service?", msg.text_sent[1])
        self.assertNotIn("ETB per 1000", "".join(msg.text_sent))
        self.assertNotIn("Facebook", "".join(msg.text_sent))
        self.assertNotIn("87.43", "".join(msg.text_sent))

    async def test_screenshot_flow_quotes_twitter_followers(self):
        # The exact screenshot flow: bare platform word, then the
        # metric, then the price — the quote must be X/Twitter's.
        bot.PARKED_DRAFT.clear()
        msg = await self._turns([
            ("Twitter", intent_of("paxyo_info")),
            ("Follower", intent_of(
                "order", platform=None, service_hint="followers",
            )),
            ("How much is it", intent_of("price")),
        ])
        self.assertEqual(len(msg.text_sent), 4)
        self.assertIn("followers, likes, views", msg.text_sent[0])
        self.assertIn(
            "Please send your X profile link.", msg.text_sent[1])
        self.assertIn(
            "unfinished order is saved", msg.text_sent[2].lower())
        reply = msg.text_sent[3]
        self.assertIn("1,260.00", reply)
        self.assertIn("Twitter", reply)
        self.assertNotIn("87.43", reply)
        self.assertNotIn("Facebook", reply)
        self.assertEqual(bot.PARKED_DRAFT[1].get("platform"), "x")

    async def test_cheapest_question_still_answers_globally(self):
        # A genuine cheapest question is answered from the
        # cheapest service on ANY platform — the guard below it
        # must not swallow that.
        msg = await self._turns([
            ("what is the cheapest followers", intent_of("price")),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("87.43", msg.text_sent[0])
        self.assertIn("Facebook", msg.text_sent[0])

    async def test_draft_with_platform_still_quotes_that_platform(self):
        bot.PARTIAL[1] = {"platform": "x", "service_hint": "followers"}
        msg = await self._turns([
            ("How much is it", intent_of("price")),
        ])
        self.assertEqual(len(msg.text_sent), 2)
        self.assertIn("1,260.00", msg.text_sent[1])
        self.assertNotIn("Facebook", msg.text_sent[1])
        self.assertNotIn("87.43", msg.text_sent[1])

    async def test_no_draft_price_question_still_asks_which_service(self):
        msg = await self._turns([
            ("How much is it", intent_of("price")),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("Which service?", msg.text_sent[0])
        self.assertNotIn("ETB per 1000", msg.text_sent[0])

    async def test_info_question_does_not_seed_platform(self):
        # "what is Twitter?" is a real info question: the answer
        # still comes back, but no platform is remembered.
        msg = await self._turns([
            ("what is Twitter?", intent_of("paxyo_info")),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("followers, likes, views", msg.text_sent[0])
        self.assertEqual(bot.PARTIAL, {})

    async def test_seed_does_not_overwrite_other_platform_draft(self):
        bot.PARTIAL[1] = {
            "platform": "tiktok", "service_hint": "views",
        }
        msg = await self._turns([
            ("Twitter", intent_of("paxyo_info")),
        ])
        self.assertEqual(len(msg.text_sent), 1)
        self.assertEqual(bot.PARTIAL[1].get("platform"), "tiktok")
        self.assertEqual(bot.PARTIAL[1].get("service_hint"), "views")

    async def test_seed_does_not_run_with_pending_card(self):
        bot.PENDING["c1"] = make_pending()
        msg = await self._turns([
            ("Twitter", intent_of("paxyo_info")),
        ])
        self.assertEqual(bot.PARTIAL, {})


class TestWidenFreeAnswers(_LanguageRoundBase):
    """Owner rule, 14 Nov 2026 (course correction): DeepSeek answers
    how-to and general questions FREELY — no big canned Q&A list.
    Deterministic answers stay only for Paxyo facts that must be
    exact (prices, comment-likes requirements, private-account
    rule, refunds to balance only, reseller/contact, paused
    services). Off-topic questions get a free answer plus ONE
    short steer-back line; on-topic how-tos get no steer-back."""

    async def test_link_howto_repro_answered_on_third_turn(self):
        # Owner repro, 14 Nov 2026: "how do I get the link of a
        # Telegram post?" got no reply — the classifier called it
        # off_topic, and from the third turn the bot only sent the
        # steer line ("I'm the Paxyo order bot — I can only help
        # with Paxyo orders."). Fix round, 14 Nov 2026: the answer
        # is now DETERMINISTIC (the AI kept getting the steps
        # wrong, and the free answer was desktop-flavoured) — the
        # AI is never called for it, on any turn.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        ai = mock.AsyncMock(
            return_value="Tap the post, then tap Copy Link."
        )
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("off_topic")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate", new=ai,
        ), mock.patch("bot.speak_reply"):
            for _ in range(3):
                await bot.handle_order_text(
                    update, None,
                    "how do I get the link of a Telegram post?",
                )
        self.assertEqual(len(msg.text_sent), 3)
        ai.assert_not_called()
        for reply in msg.text_sent:
            self.assertIn("Copy Link", reply)
            self.assertIn("share", reply.lower())
            self.assertNotIn("right-click", reply)

    async def test_off_topic_question_gets_answer_plus_steer_back(self):
        # Rule, 14 Nov 2026: an off-topic question is answered
        # freely first, then brought back to ordering with ONE
        # short line at the end.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("off_topic")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(
                return_value="Paris is the capital of France."
            ),
        ), mock.patch("bot.speak_reply"):
            await bot.handle_order_text(
                update, None, "What is the capital of France?"
            )
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("Paris is the capital", msg.text_sent[0])
        self.assertIn(
            'By the way, what would you like to order?',
            msg.text_sent[0],
        )

    async def test_how_to_intent_gets_free_answer_without_steer(self):
        # On-topic how-tos need no steer-back line: the question
        # itself is about ordering. (The Telegram post-link
        # question is now deterministic — it has its own test —
        # so this one uses a different how-to.)
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("how_to")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(
                return_value='Open your TikTok profile, your username is under your photo.'
            ),
        ), mock.patch("bot.speak_reply"):
            await bot.handle_order_text(
                update, None,
                "how do I find my TikTok username?",
            )
        self.assertEqual(
            msg.text_sent,
            ['Open your TikTok profile, your username is under your photo.'],
        )

    def test_is_question(self):
        self.assertTrue(bot.is_question("how do I get the link?"))
        self.assertTrue(bot.is_question("Who will win tonight?"))
        self.assertTrue(bot.is_question("What is the capital of France?"))
        self.assertTrue(bot.is_question("can I order for someone else"))
        self.assertFalse(bot.is_question("Tell me a story."))
        self.assertFalse(bot.is_question("haha nice"))
        self.assertFalse(bot.is_question(""))

    def test_is_comment_likes_question(self):
        self.assertTrue(
            bot.is_comment_likes_question(
                "what do I need for comment likes?"
            )
        )
        self.assertTrue(
            bot.is_comment_likes_question("how do I order comment likes?")
        )
        # An actual order (a link is pasted) is never a question.
        self.assertFalse(
            bot.is_comment_likes_question(
                "I want likes for my comment https://tiktok.com/@x/video/1"
            )
        )
        self.assertFalse(
            bot.is_comment_likes_question("I want likes for my comment")
        )

    async def test_comment_likes_question_gets_deterministic_answer(self):
        # Paxyo fact (owner, 14 Nov 2026): comment likes need the
        # video/post link plus either the comment's own link or
        # the username. Deterministic — the AI must never invent
        # a different requirement.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("paxyo_info")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(
                side_effect=AssertionError("AI must not be asked")
            ),
        ), mock.patch("bot.speak_reply"):
            await bot.handle_order_text(
                update, None, "what do I need for comment likes?"
            )
        self.assertEqual(len(msg.text_sent), 1)
        reply = msg.text_sent[0]
        self.assertIn("link of the video or post", reply)
        self.assertIn("link of the comment itself or your username", reply)

    async def test_comment_likes_order_is_not_swallowed(self):
        # A real order for comment likes still goes through the
        # order flow — the deterministic answer is only for the
        # question, never for the order itself.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of(
                "order", platform="tiktok",
                service_hint="tiktok comment likes",
                link="https://www.tiktok.com/@x/video/123",
                quantity=100,
            )),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.speak_reply"
        ):
            await bot.handle_order_text(
                update, None,
                "I want likes for my comment "
                "https://www.tiktok.com/@x/video/123 100",
            )
        self.assertTrue(msg.text_sent)
        self.assertNotIn(
            "For likes on a comment I need two things",
            " ".join(msg.text_sent),
        )

    async def test_private_account_rule_is_deterministic(self):
        # Paxyo fact: a private account can't receive the order —
        # the account must be public. The "how to make it public"
        # part is a free AI answer; the rule itself is fixed.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("paxyo_info")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.speak_reply"
        ):
            await bot.handle_order_text(
                update, None, "must my account be public to order?"
            )
        self.assertEqual(len(msg.text_sent), 1)
        self.assertIn("must be public", msg.text_sent[0])
        self.assertIn("can't receive the order", msg.text_sent[0])

    async def test_amharic_howto_answered_in_amharic(self):
        # Amharic already works (owner, 14 Nov 2026): the bridge
        # translates the question to English, DeepSeek answers
        # freely, and the reply comes back in Amharic.
        msg = FakeMessage()
        update = FakeUpdate(msg, user=FakeUser(language_code="am"))
        with mock.patch(
            "bot.translate_to_english",
            new=mock.AsyncMock(
                return_value="how do i get the link of a telegram post"
            ),
        ), mock.patch(
            "bot.translate_to_amharic",
            new=mock.AsyncMock(return_value="AMHARIC-LINK-ANSWER"),
        ), mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("off_topic")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(
                return_value="Tap the post, then tap Copy Link."
            ),
        ), mock.patch("bot.speak_reply"):
            await bot.handle_order_text(
                update, None, "የቴሌግራም ፖስት ሊንክ እንዴት አገኛለሁ?"
            )
        self.assertEqual(msg.text_sent, ["AMHARIC-LINK-ANSWER"])


