        self.assertEqual(fake.session_loads, [1])
        self.assertEqual(gem.await_args.kwargs, {"language": "am"})
        groq.assert_awaited_once()
        self.assertIn("12 ሺህ ፎሎወር እፈልጋለሁ", msg.text_sent[0])

