        bot.FIRST_ORDER_NUDGE_DONE.clear()
        bot.NUDGE_SERVICE.clear()
        bot.FAILED_DEPOSIT.clear()
        bot.FASTEST_FALLBACK.clear()
        bot.BIG_DEPOSIT_ALERTED.clear()
