            self.assertEqual(client.services_refresh_count, 1)
            by_id = {s["combined_id"]: s for s in services}
            # The live API row, tagged GodOfPanel.
            self.assertEqual(by_id["gop:1665"]["rate_etb_per_1000"], 18.90)
