    async def test_cheapest_first_pick_vs_default(self):
        # The fixture's cheapest service is the SLOWEST: default
        # (fastest first) picks a 10.00 service, cheapest-first
        # picks #5535 at 1.26.
        fake = FakePaxyo(services=_views_fixture())
