# --- New customer-bot features (19 Nov 2026): ban enforcement and
# service price overrides. ----------------------------------------

class TestApplyPriceOverrides(unittest.TestCase):
    """apply_price_overrides is pure: a (provider, service_id)
    override changes only that provider's row, never the other
    provider's same bare id."""

    def _catalogue(self):
        return [
            {"combined_id": "gop:6139", "provider": "gop",
             "provider_service_id": 6139, "rate_etb_per_1000": 126.0},
            {"combined_id": "smm:6139", "provider": "smm",
             "provider_service_id": 6139, "rate_etb_per_1000": 90.0},
            {"combined_id": "gop:1665", "provider": "gop",
             "provider_service_id": 1665, "rate_etb_per_1000": 18.9},
        ]

    def test_only_the_named_provider_changes(self):
        out = bot.apply_price_overrides(self._catalogue(), [
            {"provider": "smm", "service_id": 6139, "price_etb": 50.0},
        ])
        by_id = {s["combined_id"]: s for s in out}
        self.assertEqual(by_id["smm:6139"]["rate_etb_per_1000"], 50.0)
        self.assertTrue(by_id["smm:6139"]["price_overridden"])
        self.assertEqual(by_id["gop:6139"]["rate_etb_per_1000"], 126.0)
        self.assertNotIn("price_overridden", by_id["gop:6139"])
        self.assertEqual(by_id["gop:1665"]["rate_etb_per_1000"], 18.9)

    def test_unknown_service_and_bad_rows_are_ignored(self):
        out = bot.apply_price_overrides(self._catalogue(), [
            {"provider": "gop", "service_id": 9999, "price_etb": 50.0},
            {"provider": "gop", "service_id": 6139, "price_etb": 0},
            {"provider": "gop", "service_id": 1665, "price_etb": -5},
            {"provider": "gop", "service_id": "nope", "price_etb": 50.0},
            "not a row",
        ])
        by_id = {s["combined_id"]: s for s in out}
        self.assertEqual(by_id["gop:6139"]["rate_etb_per_1000"], 126.0)
        self.assertEqual(by_id["gop:1665"]["rate_etb_per_1000"], 18.9)
        self.assertNotIn("price_overridden", by_id["gop:6139"])

    def test_input_rows_are_not_mutated(self):
        catalogue = self._catalogue()
        before = [dict(s) for s in catalogue]
        bot.apply_price_overrides(catalogue, [
            {"provider": "smm", "service_id": 6139, "price_etb": 50.0},
        ])
        self.assertEqual(catalogue, before)

    def test_no_overrides_returns_the_same_prices(self):
        out = bot.apply_price_overrides(self._catalogue(), [])
        self.assertEqual(
            [s["rate_etb_per_1000"] for s in out],
            [126.0, 90.0, 18.9],
        )


class TestServicesPriceOverrides(unittest.IsolatedAsyncioTestCase):
    """PaxyoClient.services() applies the admin's price overrides
    in-memory before caching — quotes and order totals then use
    the edited price. A missing endpoint or a failed fetch just
    means no overrides, never a broken catalogue."""

    API_SERVICES = {
        "success": True, "count": 2, "currency": "ETB",
        "services": [
            {"id": 7246, "provider_service_id": 7246,
             "name": "Tiktok Followers", "category": "Tiktok",
             "type": "Default", "price": 525, "currency": "ETB",
             "min": 10, "max": 5000,
             "average_time": "1 hour 39 minutes", "active": True},
            {"id": 1665, "provider_service_id": 1665,
             "name": "TikTok Video Views [ Max 100M ]",
             "category": "Tiktok Services", "type": "Default",
             "price": 18.9, "currency": "ETB",
             "min": 100, "max": 100000000,
             "average_time": "1 minute", "active": True},
        ],
    }

    OVERRIDES = {"ok": True, "overrides": [
        {"provider": "gop", "service_id": 7246, "price_etb": 100.0,
         "updated_at": "2026-11-19 10:00:00"},
        {"provider": "smm", "service_id": 7013, "price_etb": 0.5,
         "updated_at": "2026-11-19 10:00:00"},
    ]}

    def _send_for(self, overrides=None, fail_overrides=None):
        def _send(request):
            if request.url.path.endswith("/admin/service-price-overrides"):
                if fail_overrides is not None:
                    raise fail_overrides
                return overrides if overrides is not None else {"ok": True, "overrides": []}
            return dict(self.API_SERVICES)
        return _send

    async def test_overrides_applied_before_caching(self):
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(
                    side_effect=self._send_for(overrides=self.OVERRIDES)
                ),
            ):
                services = await client.services()
            by_id = {s["combined_id"]: s for s in services}
            self.assertEqual(by_id["gop:7246"]["rate_etb_per_1000"], 100.0)
            self.assertTrue(by_id["gop:7246"]["price_overridden"])
            self.assertEqual(by_id["gop:1665"]["rate_etb_per_1000"], 18.9)
            self.assertNotIn("price_overridden", by_id["gop:1665"])
            # The SMM row comes from the bundled catalogue; its
            # override applies to it, not to the GOP row.
            self.assertEqual(by_id["smm:7013"]["rate_etb_per_1000"], 0.5)
            self.assertTrue(by_id["smm:7013"]["price_overridden"])
        finally:
            await client._client.aclose()

    async def test_overrides_endpoint_404_means_no_overrides(self):
        client = bot.PaxyoClient()
        try:
            req = bot.httpx.Request(
                "GET",
                "https://paxyo.et/api/bot/admin/service-price-overrides",
            )
            resp = bot.httpx.Response(
                404, json={"error": "Not found"}, request=req
            )
            error = bot.httpx.HTTPStatusError(
                "404", request=req, response=resp
            )
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(
                    side_effect=self._send_for(fail_overrides=error)
                ),
            ):
                services = await client.services()
            by_id = {s["combined_id"]: s for s in services}
            self.assertEqual(by_id["gop:7246"]["rate_etb_per_1000"], 525)
            self.assertNotIn("price_overridden", by_id["gop:7246"])
        finally:
            await client._client.aclose()

    async def test_overrides_fetch_failure_means_no_overrides(self):
        client = bot.PaxyoClient()
        try:
            with mock.patch.object(
                client, "_send",
                new=mock.AsyncMock(
                    side_effect=self._send_for(
                        fail_overrides=RuntimeError("api down")
                    )
                ),
            ):
                services = await client.services()
            by_id = {s["combined_id"]: s for s in services}
            self.assertEqual(by_id["gop:7246"]["rate_etb_per_1000"], 525)
        finally:
            await client._client.aclose()


class TestUserIsBanned(unittest.IsolatedAsyncioTestCase):
    async def test_banned_user_is_banned(self):
        with mock.patch("bot.paxyo", FakePaxyo(banned_ids={1})):
            self.assertTrue(await bot.user_is_banned(1))

    async def test_other_user_is_not_banned(self):
        with mock.patch("bot.paxyo", FakePaxyo(banned_ids={1})):
            self.assertFalse(await bot.user_is_banned(2))

    async def test_endpoint_not_live_is_not_banned(self):
        # Fail-open: a 404 (endpoint not installed yet) must never
        # block a good user.
        with mock.patch("bot.paxyo", FakePaxyo(ban_none=True)):
            self.assertFalse(await bot.user_is_banned(1))

    async def test_lookup_failure_is_not_banned(self):
        class BrokenPaxyo(FakePaxyo):
            async def get_user_ban(self, telegram_id):
                raise RuntimeError("api down")

        with mock.patch("bot.paxyo", BrokenPaxyo()):
            self.assertFalse(await bot.user_is_banned(1))

    async def test_no_client_is_not_banned(self):
        with mock.patch("bot.paxyo", None):
            self.assertFalse(await bot.user_is_banned(1))


class TestBanEnforcement(unittest.IsolatedAsyncioTestCase):
    """A banned user places nothing and deposits nothing: the
    short refusal, no money moved, no provider call."""

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot.PENDING_BATCH.clear()
        bot.PENDING_BUNDLE.clear()
        bot.LAST_ORDER.clear()

    def tearDown(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.DEPOSIT_DRAFT.clear()
        bot.PENDING_DEPOSIT.clear()
        bot.PENDING_BATCH.clear()
        bot.PENDING_BUNDLE.clear()
        bot.LAST_ORDER.clear()

    def test_banned_template_is_short_and_has_no_long_dash(self):
        for lang in ("en", "am"):
            text = bot.t("banned", lang)
            self.assertNotIn("—", text)
            self.assertIn("support", text.lower())

    async def test_place_pending_order_refuses_banned(self):
        fake = FakePaxyo(banned_ids={1})
        with mock.patch("bot.paxyo", fake):
            result, error = await bot.place_pending_order(make_pending(), 1)
        self.assertIsNone(result)
        self.assertEqual(error, ("banned",))
        self.assertEqual(fake.orders_created, [])

    async def test_place_pending_order_allows_not_banned(self):
        fake = FakePaxyo()
        with mock.patch("bot.paxyo", fake):
            result, error = await bot.place_pending_order(make_pending(), 1)
        self.assertIsNone(error)
        self.assertIsNotNone(result)
        self.assertEqual(len(fake.orders_created), 1)

    async def test_place_batch_refuses_banned(self):
        fake = FakePaxyo(banned_ids={1})
        batch = {"orders": [make_pending(), make_pending()]}
        with mock.patch("bot.paxyo", fake):
            results, error = await bot.place_batch(batch, 1)
        self.assertIsNone(results)
        self.assertEqual(error, ("banned",))
        self.assertEqual(fake.orders_created, [])

    async def test_place_bundle_refuses_banned(self):
        fake = FakePaxyo(banned_ids={1})
        bundle = {"orders": [make_pending(), make_pending()]}
        with mock.patch("bot.paxyo", fake):
            results, error = await bot.place_bundle(bundle, 1)
        self.assertIsNone(results)
        self.assertEqual(error, ("banned",))
        self.assertEqual(fake.orders_created, [])

    async def test_start_deposit_refuses_banned(self):
        fake = FakePaxyo(banned_ids={1})
        with mock.patch("bot.paxyo", fake):
            result, error = await bot.start_deposit({"amount": 100}, 1)
        self.assertIsNone(result)
        self.assertEqual(error, "banned")
        self.assertEqual(fake.deposits_created, [])

    async def test_refill_confirm_refuses_banned(self):
        fake = FakePaxyo(banned_ids={1})
        sent = []

        async def respond(text, reply_markup=None):
            sent.append(text)

        async def send_new(text, reply_markup=None):
            sent.append(text)

        with mock.patch("bot.paxyo", fake):
            await bot._run_refill_confirm(
                1, {"order_id": 1841}, "en",
                respond=respond, send_new=send_new,
            )
        self.assertEqual(sent, [bot.t("banned", "en")])
        self.assertEqual(fake.refill_calls, [])

    async def test_delayed_order_never_places_for_banned(self):
        fake = FakePaxyo(balance=1000.0, banned_ids={1})
        by_id = {
            1001: SAMPLE_SERVICES[0],
            "gop:1001": SAMPLE_SERVICES[0],
        }
        item = {
            "id": 101, "telegram_id": 1, "service_id": 1001,
            "provider": "gop", "combined_id": "gop:1001",
            "link": "https://instagram.com/someuser", "quantity": 100,
            "total": 4.2, "run_at": "2026-11-15 19:00:00",
            "status": "scheduled", "idempotency_key": "delay-1",
        }
        app = FakeApp()
        with mock.patch("bot.paxyo", fake):
            await bot.run_one_delayed(app, item, by_id)
        self.assertEqual(fake.orders_created, [])
        self.assertEqual(fake.delayed_finished, [{
            "id": 101, "status": "failed", "order_id": None,
            "reason": "account is blocked",
        }])
        self.assertEqual(len(app.bot.sent), 1)
        self.assertIn("blocked", app.bot.sent[0][1])

    async def test_recurring_schedule_pauses_for_banned(self):
        fake = FakePaxyo(due=[due_schedule()], banned_ids={1})
        app = FakeApp()
        with mock.patch("bot.paxyo", fake):
            await bot.run_scheduler_cycle(app)
        self.assertEqual(fake.orders_created, [])
        self.assertEqual(fake.recurring_paused, [7])
        self.assertEqual(fake.recurring_ran, [])
        self.assertEqual(len(app.bot.sent), 1)
        self.assertIn("blocked", app.bot.sent[0][1])


class TestAutoRefillParsing(unittest.TestCase):
    """Auto-refill request detection and target parsing (19 Nov 2026)."""

    def test_target_above_k(self):
        self.assertEqual(
            bot.parse_auto_refill_target("keep my followers above 15k"), 15000)

    def test_target_plain_number(self):
        self.assertEqual(
            bot.parse_auto_refill_target("keep it above 15000"), 15000)

    def test_target_at_least(self):
        self.assertEqual(
            bot.parse_auto_refill_target("keep my views at least 10k"), 10000)

    def test_target_word(self):
        self.assertEqual(
            bot.parse_auto_refill_target("target 10k views"), 10000)

    def test_target_none_without_trigger(self):
        self.assertIsNone(bot.parse_auto_refill_target("order 1000 views"))
        self.assertIsNone(bot.parse_auto_refill_target("my balance is 100"))
        self.assertIsNone(bot.parse_auto_refill_target(""))

    def test_is_request_keep_above(self):
        self.assertTrue(
            bot.is_auto_refill_request("keep my followers above 15k"))
        self.assertTrue(
            bot.is_auto_refill_request("keep my tiktok views above 10k"))
        self.assertTrue(
            bot.is_auto_refill_request("don't let my views fall under 5000"))
        self.assertTrue(
            bot.is_auto_refill_request("auto refill my TikTok views"))
        self.assertTrue(
            bot.is_auto_refill_request(
                "top up my views when they drop below 10k"))

    def test_is_request_rejects_panel_refill_and_orders(self):
        # A panel refill ("it stopped at 800 out of 1000, send the
        # rest") must stay a plain "refill", never an auto-refill.
        self.assertFalse(
            bot.is_auto_refill_request(
                "it stopped at 800 out of 1000, send the rest"))
        self.assertFalse(bot.is_auto_refill_request("order 1000 views"))
        self.assertFalse(bot.is_auto_refill_request("how much is 10k views"))

    def test_status_and_stop_detection(self):
        self.assertTrue(
            bot.is_auto_refill_status_request("my auto refills"))
        self.assertTrue(
            bot.is_auto_refill_status_request("auto refill status"))
        self.assertFalse(
            bot.is_auto_refill_status_request("refill status"))
        self.assertTrue(
            bot.is_auto_refill_stop_request("stop auto refill"))
        self.assertTrue(
            bot.is_auto_refill_stop_request("turn off auto refill"))
        self.assertFalse(
            bot.is_auto_refill_stop_request("stop my repeating order"))

    def test_local_intent_detects_auto_refill(self):
        intent = bot.local_intent("keep my followers above 15k")
        self.assertEqual(intent["intent"], "auto_refill")
        self.assertEqual(intent["target"], 15000)
        intent = bot.local_intent("top up my views when they drop below 10k")
        self.assertEqual(intent["intent"], "auto_refill")
        self.assertEqual(intent["target"], 10000)


class TestAutoRefillGuards(unittest.TestCase):
    """Trigger and daily cap (owner, 20 Nov 2026): 5% drop by
    default, no daily cap unless the user sets one."""

    SERVICE = {
        "service": 2001, "name": "TikTok Video Views | Fast",
        "rate_etb_per_1000": 18.9, "min": 10, "max": 1000000,
    }

    def test_min_drop_five_percent_default(self):
        self.assertEqual(bot.auto_refill_min_drop(1000), 50)
        self.assertEqual(bot.auto_refill_min_drop(4000), 200)
        self.assertEqual(bot.auto_refill_min_drop(15000), 750)
        self.assertEqual(bot.auto_refill_min_drop(1000000), 50000)

    def test_min_drop_bad_input(self):
        self.assertEqual(bot.auto_refill_min_drop(None), 1)
        self.assertEqual(bot.auto_refill_min_drop(0), 1)

    def test_min_drop_user_trigger_quantity(self):
        trigger = {"type": "qty", "value": 200}
        self.assertEqual(
            bot.auto_refill_min_drop(15000, trigger=trigger), 200)
        self.assertEqual(
            bot.auto_refill_min_drop(1000, trigger=trigger), 200)

    def test_min_drop_user_trigger_percent(self):
        trigger = {"type": "pct", "value": 0.10}
        self.assertEqual(
            bot.auto_refill_min_drop(15000, trigger=trigger), 1500)
        self.assertEqual(
            bot.auto_refill_min_drop(1000, trigger=trigger), 100)

    def test_min_drop_bad_trigger_falls_back_to_default(self):
        self.assertEqual(
            bot.auto_refill_min_drop(15000, trigger={"type": "qty", "value": 0}),
            750)
        self.assertEqual(
            bot.auto_refill_min_drop(15000, trigger={"type": "pct", "value": 1.5}),
            750)
        self.assertEqual(
            bot.auto_refill_min_drop(15000, trigger={"type": "bogus", "value": 5}),
            750)

    def test_top_up_quantity(self):
        self.assertEqual(
            bot.auto_refill_top_up_qty(14000, 15000, self.SERVICE), 1000)

    def test_top_up_rounds_up_to_ten(self):
        self.assertEqual(
            bot.auto_refill_top_up_qty(14245, 15000, self.SERVICE), 760)

    def test_top_up_none_when_drop_too_small(self):
        self.assertIsNone(
            bot.auto_refill_top_up_qty(14950, 15000, self.SERVICE))
        self.assertIsNone(
            bot.auto_refill_top_up_qty(14300, 15000, self.SERVICE))

    def test_top_up_none_when_at_or_above_target(self):
        self.assertIsNone(
            bot.auto_refill_top_up_qty(15000, 15000, self.SERVICE))
        self.assertIsNone(
            bot.auto_refill_top_up_qty(16000, 15000, self.SERVICE))

    def test_top_up_never_below_service_minimum(self):
        service = dict(self.SERVICE, min=1000)
        self.assertEqual(
            bot.auto_refill_top_up_qty(14240, 15000, service), 1000)

    def test_top_up_with_user_trigger_quantity(self):
        trigger = {"type": "qty", "value": 200}
        self.assertEqual(
            bot.auto_refill_top_up_qty(
                14800, 15000, self.SERVICE, trigger=trigger), 200)
        self.assertIsNone(
            bot.auto_refill_top_up_qty(
                14850, 15000, self.SERVICE, trigger=trigger))

    def test_decide_top_up_with_cost(self):
        decision = bot.auto_refill_decide(
            14000, 15000, self.SERVICE, spent_today=0)
        self.assertEqual(decision["action"], "top_up")
        self.assertEqual(decision["quantity"], 1000)
        self.assertEqual(decision["cost"], 18.9)

    def test_decide_no_cap_by_default(self):
        # No daily cap unless the user set one: even 990 ETB
        # already spent today does not stop a top-up.
        decision = bot.auto_refill_decide(
            14000, 15000, self.SERVICE, spent_today=990.0)
        self.assertEqual(decision["action"], "top_up")
        decision = bot.auto_refill_decide(
            14000, 15000, self.SERVICE, spent_today=5000.0)
        self.assertEqual(decision["action"], "top_up")

    def test_decide_user_cap_respected(self):
        decision = bot.auto_refill_decide(
            14000, 15000, self.SERVICE, spent_today=990.0, cap=1000.0)
        self.assertEqual(decision["action"], "cap")
        self.assertEqual(decision["quantity"], 1000)
        decision = bot.auto_refill_decide(
            14000, 15000, self.SERVICE, spent_today=0, cap=1000.0)
        self.assertEqual(decision["action"], "top_up")

    def test_decide_skip_at_target_and_small_drop(self):
        self.assertEqual(
            bot.auto_refill_decide(
                15000, 15000, self.SERVICE, spent_today=0)["action"],
            "skip")
        self.assertEqual(
            bot.auto_refill_decide(
                14950, 15000, self.SERVICE, spent_today=0)["reason"],
            "drop_too_small")

    def test_decide_unavailable_without_count(self):
        self.assertEqual(
            bot.auto_refill_decide(
                None, 15000, self.SERVICE, spent_today=0)["action"],
            "unavailable")


class TestAutoRefillGuardParsing(unittest.TestCase):
    """The setup's trigger and daily-limit answers, in plain
    words (owner, 20 Nov 2026)."""

    def test_parse_trigger_quantity(self):
        self.assertEqual(
            bot.parse_auto_refill_trigger("when it drops by 200"),
            {"type": "qty", "value": 200})
        self.assertEqual(
            bot.parse_auto_refill_trigger("drop 200"),
            {"type": "qty", "value": 200})
        self.assertEqual(
            bot.parse_auto_refill_trigger("200"),
            {"type": "qty", "value": 200})

    def test_parse_trigger_percent(self):
        self.assertEqual(
            bot.parse_auto_refill_trigger("10%"),
            {"type": "pct", "value": 0.10})
        self.assertEqual(
            bot.parse_auto_refill_trigger("when it drops 10 percent"),
            {"type": "pct", "value": 0.10})
        self.assertEqual(
            bot.parse_auto_refill_trigger("drops 2.5%"),
            {"type": "pct", "value": 0.025})

    def test_parse_trigger_keeps_default(self):
        self.assertIsNone(bot.parse_auto_refill_trigger("ok"))
        self.assertIsNone(bot.parse_auto_refill_trigger("yes"))
        self.assertIsNone(bot.parse_auto_refill_trigger(""))
        self.assertIsNone(bot.parse_auto_refill_trigger("100%"))
        self.assertIsNone(bot.parse_auto_refill_trigger("0"))

    def test_parse_daily_cap(self):
        self.assertEqual(
            bot.parse_auto_refill_daily_cap("limit 1000 a day"), 1000.0)
        self.assertEqual(
            bot.parse_auto_refill_daily_cap("max 500 a day"), 500.0)
        self.assertEqual(
            bot.parse_auto_refill_daily_cap("cap 1000 ETB"), 1000.0)

    def test_parse_daily_cap_none(self):
        self.assertIsNone(bot.parse_auto_refill_daily_cap("no limit"))
        self.assertIsNone(bot.parse_auto_refill_daily_cap("ok"))
        self.assertIsNone(bot.parse_auto_refill_daily_cap("unlimited"))
        # A bare number is a trigger quantity, never a cap.
        self.assertIsNone(bot.parse_auto_refill_daily_cap("1000"))

    def test_trigger_text(self):
        self.assertEqual(
            bot.auto_refill_trigger_text(None, 10000, "en"),
            "when it drops 5% below 10,000")
        self.assertEqual(
            bot.auto_refill_trigger_text(
                {"type": "qty", "value": 200}, 10000, "en"),
            "when it drops by 200")
        self.assertEqual(
            bot.auto_refill_trigger_text(
                {"type": "pct", "value": 0.10}, 10000, "en"),
            "when it drops 10% below 10,000")

    def test_limit_text(self):
        self.assertEqual(
            bot.auto_refill_limit_text(None, "en"),
            "There is no daily limit — I can use your whole balance.")
        self.assertEqual(
            bot.auto_refill_limit_text(1000.0, "en"),
            "At most 1,000.00 ETB a day.")


class TestCountParsing(unittest.TestCase):
    """Count parsing: compact numbers, provider payloads, and the
    recorded sample pages (no live fetches)."""

    def test_compact_count(self):
        self.assertEqual(bot.parse_compact_count("5,178 views"), 5178)
        self.assertEqual(bot.parse_compact_count("12.3K subscribers"), 12300)
        self.assertEqual(bot.parse_compact_count("1.2M"), 1200000)
        self.assertEqual(bot.parse_compact_count("5178"), 5178)
        self.assertIsNone(bot.parse_compact_count("no number here"))
        self.assertIsNone(bot.parse_compact_count(None))

    def test_deep_find_count(self):
        payload = {"data": {"statistics": {"play_count": 5178}}}
        self.assertEqual(
            bot._deep_find_count(payload, ["play_count"]), 5178)
        self.assertEqual(
            bot._deep_find_count({"play_count": 42}, ["play_count"]), 42)
        self.assertIsNone(
            bot._deep_find_count({"data": {}}, ["play_count"]))

    def test_ensembledata_count_nested_and_flat(self):
        # Recorded shape, verified live 19 Nov 2026 on video
        # 7666462351436107015: 5,178 views, 7 likes, 0 comments,
        # 1 share.
        nested = {
            "success": True,
            "data": {
                "aweme_id": "7666462351436107015",
                "statistics": {
                    "play_count": 5178, "digg_count": 7,
                    "comment_count": 0, "share_count": 1,
                },
            },
        }
        self.assertEqual(
            bot.parse_ensembledata_count(nested, "play_count"), 5178)
        flat = {"success": True, "data": {"play_count": 5178}}
        self.assertEqual(
            bot.parse_ensembledata_count(flat, "play_count"), 5178)
        self.assertIsNone(
            bot.parse_ensembledata_count({"success": False}, "play_count"))
        self.assertIsNone(
            bot.parse_ensembledata_count("not a dict", "play_count"))

    def test_tiktok_page_video_and_profile(self):
        video_page = (
            "<html><body>"
            '<script id="SIGI_STATE" type="application/json">'
            '{"ItemModule":{"7666462351436107015":'
            '{"stats":{"playCount":5178,"diggCount":7},'
            '"author":"paxyo251"}}}</script>'
            "</body></html>"
        )
        self.assertEqual(
            bot.parse_tiktok_page_count(video_page, "views"), 5178)
        profile_page = (
            "<html><body>"
            '<script id="SIGI_STATE" type="application/json">'
            '{"UserModule":{"users":{"paxyo251":'
            '{"stats":{"followerCount":12345}}}}}</script>'
            "</body></html>"
        )
        self.assertEqual(
            bot.parse_tiktok_page_count(profile_page, "followers"), 12345)
        self.assertIsNone(
            bot.parse_tiktok_page_count("<html></html>", "views"))

    def test_youtube_page_video_and_channel(self):
        video_data = {
            "contents": {"twoColumnWatchNextResults": {"results": {"results": {
                "contents": [{"videoPrimaryInfoRenderer": {"viewCount": {
                    "videoViewCountRenderer": {"viewCount": {
                        "simpleText": "5,178 views"}}}}}]}}}}},
        video_page = (
            "<html><body><script>"
            f"var ytInitialData = {json.dumps(video_data)};"
            "</script></body></html>"
        )
        self.assertEqual(
            bot.parse_youtube_page_count(video_page, "views"), 5178)
        channel_data = {
            "header": {"c4TabbedHeaderRenderer": {"subscriberCountText": {
                "simpleText": "12.3K subscribers"}}},
        }
        channel_page = (
            "<html><body><script>"
            f"var ytInitialData = {json.dumps(channel_data)};"
            "</script></body></html>"
        )
        self.assertEqual(
            bot.parse_youtube_page_count(channel_page, "subscribers"), 12300)
        self.assertIsNone(
            bot.parse_youtube_page_count("<html></html>", "views"))

    def test_telegram_page(self):
        page = (
            '<div class="tgme_page">'
            '<div class="tgme_page_extra">1,234 subscribers</div>'
            "</div>"
        )
        self.assertEqual(bot.parse_telegram_page_count(page), 1234)
        page_k = '<div class="tgme_page_extra">12.3K subscribers</div>'
        self.assertEqual(bot.parse_telegram_page_count(page_k), 12300)
        self.assertIsNone(bot.parse_telegram_page_count("<html></html>"))

    def test_youtube_id_from_link(self):
        self.assertEqual(
            bot._youtube_id_from_link(
                "https://www.youtube.com/watch?v=dQw4w9WgXcQ"),
            ("video", "dQw4w9WgXcQ"))
        self.assertEqual(
            bot._youtube_id_from_link("https://youtu.be/dQw4w9WgXcQ"),
            ("video", "dQw4w9WgXcQ"))
        self.assertEqual(
            bot._youtube_id_from_link(
                "https://www.youtube.com/channel/UC1234567890abcdef"),
            ("channel", "UC1234567890abcdef"))
        self.assertEqual(
            bot._youtube_id_from_link("https://www.youtube.com/@paxyo251"),
            ("handle", "paxyo251"))
        self.assertIsNone(
            bot._youtube_id_from_link("https://example.com/not-youtube"))

    def test_telegram_chat_from_link(self):
        self.assertEqual(
            bot._telegram_chat_from_link("https://t.me/paxyo251"), "@paxyo251")
        self.assertEqual(
            bot._telegram_chat_from_link("https://t.me/c/123456"),
            "-100123456")
        self.assertIsNone(
            bot._telegram_chat_from_link("https://t.me/+abcdef"))


class TestCountUsage(unittest.TestCase):
    """Per-provider daily usage tracking (lives in the refill record)."""

    DAY = 1760000000  # a fixed UTC day; +86400 is the next day

    def test_budget_enforced(self):
        usage = bot.CountUsage()
        self.assertTrue(usage.can_use("ensembledata", 2, now=self.DAY))
        usage.record("ensembledata", 48, now=self.DAY)
        self.assertTrue(usage.can_use("ensembledata", 2, now=self.DAY))
        self.assertFalse(usage.can_use("ensembledata", 3, now=self.DAY))
        usage.record("ensembledata", 2, now=self.DAY)
        self.assertEqual(usage.used_today("ensembledata", now=self.DAY), 50)
        self.assertFalse(usage.can_use("ensembledata", 1, now=self.DAY))

    def test_daily_reset(self):
        usage = bot.CountUsage()
        usage.record("ensembledata", 50, now=self.DAY)
        self.assertEqual(
            usage.used_today("ensembledata", now=self.DAY + 86400), 0)
        self.assertTrue(
            usage.can_use("ensembledata", 2, now=self.DAY + 86400))

    def test_park_after_rate_limit(self):
        usage = bot.CountUsage()
        usage.park("ensembledata", seconds=3600, now=self.DAY)
        self.assertTrue(usage.is_parked("ensembledata", now=self.DAY))
        self.assertFalse(usage.can_use("ensembledata", 1, now=self.DAY))
        self.assertFalse(
            usage.is_parked("ensembledata", now=self.DAY + 3601))

    def test_total_budget_enforced_and_survives_day_rollover(self):
        # SocialHolmes' 1,000 free results are one-time, not
        # daily: the total is enforced, and a new day resets the
        # daily count but NOT the total.
        usage = bot.CountUsage()
        usage.record("socialholmes", 999, now=self.DAY)
        self.assertEqual(usage.total_used("socialholmes"), 999)
        self.assertTrue(usage.can_use("socialholmes", 1, now=self.DAY))
        usage.record("socialholmes", 1, now=self.DAY)
        self.assertEqual(usage.total_used("socialholmes"), 1000)
        self.assertFalse(usage.can_use("socialholmes", 1, now=self.DAY))
        self.assertEqual(
            usage.used_today("socialholmes", now=self.DAY + 86400), 0)
        self.assertFalse(
            usage.can_use("socialholmes", 1, now=self.DAY + 86400))
        self.assertEqual(usage.total_used("socialholmes"), 1000)

    def test_total_used_round_trip(self):
        usage = bot.CountUsage()
        usage.record("socialholmes", 7, now=self.DAY)
        restored = bot.CountUsage(usage.to_dict())
        self.assertEqual(restored.total_used("socialholmes"), 7)
        self.assertTrue(restored.can_use("socialholmes", 1, now=self.DAY))

    def test_no_budget_providers_never_blocked(self):
        usage = bot.CountUsage()
        self.assertTrue(usage.can_use("own_scraper", 0, now=self.DAY))
        self.assertTrue(usage.can_use("telegram", 0, now=self.DAY))

    def test_round_trip(self):
        usage = bot.CountUsage()
        usage.record("ensembledata", 4, now=self.DAY)
        restored = bot.CountUsage(usage.to_dict())
        self.assertEqual(
            restored.used_today("ensembledata", now=self.DAY), 4)


class TestCountChain(unittest.IsolatedAsyncioTestCase):
    """The fallback chain: own scraper first, then the free APIs.
    No live calls — every provider answers from canned replies."""

    ENSEMBLEDATA_VIDEO = json.dumps({
        "success": True,
        "data": {
            "aweme_id": "7666462351436107015",
            "statistics": {
                "play_count": 5178, "digg_count": 7,
                "comment_count": 0, "share_count": 1,
            },
        },
    })
    SCRAPEEVERYTHING_VIDEO = json.dumps({
        "success": True,
        "data": {
            "id": "7666462351436107015",
            "play_count": 6000, "like_count": 9,
        },
        "meta": {"credits_charged": 1, "credits_remaining": 99},
    })
    SOCIALHOLMES_RUN = json.dumps({
        "id": "run_1", "status": "queued", "platform": "tiktok",
        "endpoint": "video", "target": "7666462351436107015",
        "requested": 1, "created_at": "2026-11-19T23:00:00Z",
    })
    SOCIALHOLMES_DONE = json.dumps({
        "id": "run_1", "status": "succeeded", "platform": "tiktok",
        "endpoint": "video", "target": "7666462351436107015",
        "requested": 1, "result_count": 1,
        "finished_at": "2026-11-19T23:00:05Z",
    })
    SOCIALHOLMES_VIDEO_RESULTS = json.dumps({
        "results": [{"type": "video", "play_count": 5178}],
    })
    SOCIALHOLMES_PROFILE_RESULTS = json.dumps({
        "results": [{"type": "profile", "username": "paxyo251",
                     "follower_count": 1234}],
    })
    YOUTUBE_VIDEO = json.dumps({
        "items": [{"statistics": {
            "viewCount": "5178", "likeCount": "7"}}],
    })
    TELEGRAM_COUNT = json.dumps({"ok": True, "result": 12345})
    TIKTOK_PAGE = (
        "<html><body>"
        '<script id="SIGI_STATE" type="application/json">'
        '{"ItemModule":{"7666462351436107015":'
        '{"stats":{"playCount":5178}}}}'
        "</script></body></html>"
    )
    EMPTY_PAGE = "<html><body>nothing here</body></html>"

    LINK = "https://www.tiktok.com/@paxyo251/video/7666462351436107015"
    TOKENS = {
        "ensembledata": "test-ensemble-token",
        "socialholmes": "test-holmes-token",
        "scrapeeverything": "test-scrape-key",
        "youtube": "test-yt-key",
        "telegram": "test-bot-token",
    }

    def setUp(self):
        bot._COUNT_CACHE.clear()

    def tearDown(self):
        bot._COUNT_CACHE.clear()

    def _fake_http(self, mapping):
        """{(method, url-needle): (status, body)} — raises on any
        call the test did not plan, so a provider the chain should
        not reach is caught, not silently served."""
        calls = []

        async def fake_http(method, url, params=None, json_body=None,
                            headers=None, proxy=None, timeout=10.0):
            calls.append((method, url, proxy))
            for (m, needle), (status, body) in mapping.items():
                if m == method and needle in url:
                    return status, body
            raise AssertionError(f"unexpected count call {method} {url}")

        fake_http.calls = calls
        return fake_http

    async def test_own_scraper_wins_and_costs_nothing(self):
        http_get = self._fake_http({
            ("GET", "tiktok.com"): (200, self.TIKTOK_PAGE),
        })
        count, provider, cost, usage = await bot.fetch_live_count(
            "tiktok", "views", self.LINK, tokens=dict(self.TOKENS),
            http_get=http_get,
        )
        self.assertEqual((count, provider, cost), (5178, "own_scraper", 0))
        self.assertEqual(usage, {})
        self.assertEqual(len(http_get.calls), 1)

    async def test_scraper_blocked_falls_to_ensembledata(self):
        http_get = self._fake_http({
            ("GET", "tiktok.com"): (403, "blocked"),
            ("GET", "ensembledata.com"): (200, self.ENSEMBLEDATA_VIDEO),
        })
        count, provider, cost, usage = await bot.fetch_live_count(
            "tiktok", "views", self.LINK, tokens=dict(self.TOKENS),
            http_get=http_get,
        )
        self.assertEqual((count, provider, cost), (5178, "ensembledata", 2))
        self.assertEqual(usage["ensembledata"]["used"], 2)

    async def test_scraper_parse_failure_falls_through(self):
        http_get = self._fake_http({
            ("GET", "tiktok.com"): (200, self.EMPTY_PAGE),
            ("GET", "ensembledata.com"): (200, self.ENSEMBLEDATA_VIDEO),
        })
        count, provider, _cost, _usage = await bot.fetch_live_count(
            "tiktok", "views", self.LINK, tokens=dict(self.TOKENS),
            http_get=http_get,
        )
        self.assertEqual((count, provider), (5178, "ensembledata"))

    async def test_ensembledata_over_budget_skips_to_scrapeeverything(self):
        usage = {"ensembledata": {"date": "2026-11-19", "used": 49,
                                  "backoff_until": 0}}
        http_get = self._fake_http({
            ("GET", "tiktok.com"): (200, self.EMPTY_PAGE),
            ("POST", "api.scrapeeverything.com"): (
                200, self.SCRAPEEVERYTHING_VIDEO),
        })
        # The date must be "today" for the budget to bind: use the
        # tracker's own today for the seeded entry.
        today = bot.CountUsage()._today()
        usage = {"ensembledata": {"date": today, "used": 49,
                                  "backoff_until": 0}}
        count, provider, cost, out = await bot.fetch_live_count(
            "tiktok", "views", self.LINK, usage=usage,
            tokens=dict(self.TOKENS, socialholmes=None),
            http_get=http_get,
        )
        self.assertEqual((count, provider, cost),
                         (6000, "scrapeeverything", 1))
        self.assertEqual(out["ensembledata"]["used"], 49)

    async def test_rate_limit_parks_provider_and_falls_through(self):
        http_get = self._fake_http({
            ("GET", "tiktok.com"): (200, self.EMPTY_PAGE),
            ("GET", "ensembledata.com"): (429, "too many requests"),
            ("POST", "api.scrapeeverything.com"): (
                200, self.SCRAPEEVERYTHING_VIDEO),
        })
        count, provider, _cost, usage = await bot.fetch_live_count(
            "tiktok", "views", self.LINK, tokens=dict(
                self.TOKENS, socialholmes=None), http_get=http_get,
        )
        self.assertEqual((count, provider), (6000, "scrapeeverything"))
        self.assertGreater(
            usage["ensembledata"]["backoff_until"], 0)

    async def test_socialholmes_video_run_succeeds(self):
        # EnsembleData unconfigured and the scraper blocked: the
        # chain reaches SocialHolmes, which starts a run, polls
        # it to succeeded and reads play_count out of the
        # results. One delivered result costs 1 out of the
        # 1,000-result free allowance.
        tokens = dict(self.TOKENS, ensembledata=None)
        http_get = self._fake_http({
            ("GET", "tiktok.com"): (403, "blocked"),
            ("POST", "scrape/tiktok/video"): (202, self.SOCIALHOLMES_RUN),
            ("GET", "/runs/run_1/results"): (
                200, self.SOCIALHOLMES_VIDEO_RESULTS),
            ("GET", "/runs/run_1"): (200, self.SOCIALHOLMES_DONE),
        })
        count, provider, cost, usage = await bot.fetch_live_count(
            "tiktok", "views", self.LINK, tokens=tokens, http_get=http_get,
        )
        self.assertEqual((count, provider, cost), (5178, "socialholmes", 1))
        self.assertEqual(usage["socialholmes"]["used"], 1)
        self.assertEqual(usage["socialholmes"]["total_used"], 1)

