        msg = await self._build_preview_with_guards("when it drops by 200")
        self.assertIn("when it drops by 200", msg.text_sent[0])
        confirm_id = next(iter(bot.PENDING_AUTO_REFILL))
        setup = bot.PENDING_AUTO_REFILL[confirm_id]
