        msg = await self._build_preview_with_guards("10%")
        self.assertIn("when it drops 10% below 10,000", msg.text_sent[0])
        confirm_id = next(iter(bot.PENDING_AUTO_REFILL))
        setup = bot.PENDING_AUTO_REFILL[confirm_id]
